INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.f', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART', 'f', 'value appreciation of Creative Arts works drawn from various cultural backgrounds', 'kicd_verified') ON CONFLICT (code) DO NOTHING;
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.ID', 'CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR', 'creative_arts', 4, 'Identify indigenous percussion instruments, their community and how they are played', ARRAY['CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.a']::text[], 'The child names the ngoma (drum), the isukuti (Luhya drum) and the kayamba (shaker of the coast) as percussion instruments, knows percussion instruments are hit, shaken or scraped, and does not put the nyatiti, orutu or nzumari in the percussion group. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G4.RUBRIC.1.1), never as a phone question: d) improvise rhythmic patterns using indigenous percussion musical instruments.', '["pick the percussion instrument from a list","say how an instrument is played","match an instrument to its community","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.CLASSIFY', 'CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR', 'creative_arts', 4, 'Classify percussion instruments as melodic or non-melodic', ARRAY['CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.b']::text[], 'The child says a melodic percussion instrument can make notes of different pitch so it can play a tune (a xylophone, a marimba or a set of tuned bars), a non-melodic one makes sounds without a tune (a kayamba, a shaker, a rattle, clapping sticks, a single drum), and does not decide by loudness. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say which group an instrument belongs to","say what melodic means","pick the instrument that can play a tune","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.DRUMPARTS', 'CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR', 'creative_arts', 4, 'Say what the parts of a drum do', ARRAY['CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.c']::text[], 'The child says the skin vibrates when it is hit and that is the sound, the shell holds the air and makes the sound fuller, a tighter skin gives a higher sound and a looser skin a lower one, a bigger drum gives a lower sound, and the stick or hand is what hits the skin. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the part from its job","say what a part does to the sound","say what makes a drum higher or lower","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.CHARCOAL', 'CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR', 'creative_arts', 4, 'Describe how charcoal sticks are made and what smudging does', ARRAY['CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.e', 'CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.f']::text[], 'The child puts the steps in order: cut straight twigs and trim them, wrap them tightly in foil or put them in a closed tin, burn them with little air by an adult, let them cool fully, then use them. The child says smudging with a finger or cloth spreads the charcoal to make soft light and dark areas (tonal value), pressing harder makes it darker, and the fire step is done by an adult. This is the knowledge half of outcomes e and f; drawing is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G4.RUBRIC.1.1), never as a phone question: e) make charcoal sticks for drawing; f) create tonal value on a drawing of a percussion instrument using the smudging technique.', '["put the steps of making a charcoal stick in order","say what smudging does to a drawing","say what is done safely and who does it","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.CREATI.NETBALL.PASSES', 'CREA.G4.CREATI.NETBALL', 'creative_arts', 4, 'Describe the chest pass, the overhead pass and double-handed catching', ARRAY['CREA.G4.CREATI.NETBALL.a']::text[], 'The child says a chest pass is thrown from the chest with two hands, an overhead pass is thrown from above the head with two hands, a double-handed catch uses both hands with fingers spread and eyes on the ball, the catcher moves to the ball and brings it in toward the chest, and the thrower looks at the catcher. This is the knowledge half of outcome a; passing is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G4.RUBRIC.1.1), never as a phone question: c) perform the skills of passing, and catching in Netball.', '["name the pass from how it is thrown","say how a good catch is made","pick the careful action in a game story","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.CREATI.NETBALL.MACRAME', 'CREA.G4.CREATI.NETBALL', 'creative_arts', 4, 'Put the steps of making a macramé ball in order', ARRAY['CREA.G4.CREATI.NETBALL.b']::text[], 'The child says macramé is made by tying knots (not sewing or gluing), the overhand knot is made by making a loop and passing the end through it before pulling tight, the ball is made by knotting strands round a soft core (old cloth or paper), and string, sisal, plastic bag strips and strips of old cloth are reusable materials. This is the knowledge half of outcome b; making the ball is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G4.RUBRIC.1.1), never as a phone question: b) make a ball using macramé technique.', '["put the steps in order","say what the overhand knot is","pick a reusable material","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.COLOURS', 'CREA.G4.CREATI.PAINTING_AND_MONTAGE', 'creative_arts', 4, 'Classify colours as primary or secondary', ARRAY['CREA.G4.CREATI.PAINTING_AND_MONTAGE.a']::text[], 'The child names red, yellow and blue as the primary colours (they cannot be made by mixing) and orange, green and purple as the secondary colours (each made by mixing two primaries), and does not call green, black or white primary. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the primary colours","pick the secondary colours","say whether a colour is primary or secondary","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.MIX', 'CREA.G4.CREATI.PAINTING_AND_MONTAGE', 'creative_arts', 4, 'Say which two primary colours make each secondary colour', ARRAY['CREA.G4.CREATI.PAINTING_AND_MONTAGE.a']::text[], 'The child says red and yellow make orange, blue and yellow make green, and red and blue make purple, and picks the right pair when a painter needs one of them. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say what two colours make a secondary","say what a mix makes","pick the pair a painter needs","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.VALUE', 'CREA.G4.CREATI.PAINTING_AND_MONTAGE', 'creative_arts', 4, 'Say how white and black change the value of a colour', ARRAY['CREA.G4.CREATI.PAINTING_AND_MONTAGE.b']::text[], 'The child says colour value is how light or dark a colour is, adding white makes a lighter tone, adding black makes a darker tone, a value scale strip goes from light to dark in small steps, and adding a little at a time keeps control. This is the knowledge half of outcome b; painting is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G4.RUBRIC.1.1), never as a phone question: b) paint a picture for colour value application.', '["say what white or black does to a colour","say what colour value means","order a value scale","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.MONTAGE', 'CREA.G4.CREATI.PAINTING_AND_MONTAGE', 'creative_arts', 4, 'Describe a montage and how it is made', ARRAY['CREA.G4.CREATI.PAINTING_AND_MONTAGE.c']::text[], 'The child says a montage is a picture made from many pictures cut out and pasted together on a theme (such as ball games), the pieces overlap so that no gaps show, the steps are to find and cut pictures, plan the arrangement, paste and then clean up, and a neat montage has clean edges and little glue showing. This is the knowledge half of outcome c; making it is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G4.RUBRIC.1.1), never as a phone question: c) create a montage composition for expression.', '["say what a montage is","put the montage steps in order","say what makes a montage neat","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.CREATI.RHYTHM.VALUES', 'CREA.G4.CREATI.RHYTHM', 'creative_arts', 4, 'Say how many beats a crotchet, a pair of quavers and their rests last', ARRAY['CREA.G4.CREATI.RHYTHM.a']::text[], 'The child says a crotchet lasts one beat, a pair of quavers lasts one beat together (each quaver is half a beat), a crotchet rest is one beat of silence and a quaver rest is half a beat of silence, and that a rest is counted but not sounded. Shapes, signs and holes are described in words, because the phone question has no staff or picture. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say the beats of a note or rest","say how a note looks in words","add the beats of a short pattern","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.CREATI.RHYTHM.NAMES', 'CREA.G4.CREATI.RHYTHM', 'creative_arts', 4, 'Match the French rhythm names taa and ta-te to the notes', ARRAY['CREA.G4.CREATI.RHYTHM.a', 'CREA.G4.CREATI.RHYTHM.b']::text[], 'The child matches taa to the crotchet (one sound in one beat) and ta-te to a pair of quavers (two sounds in one beat), says a rest is silent so it has no name to say aloud, and counts beats and not sounds. This is the knowledge half of outcome b; writing the names in lettering is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["match a French name to a note","say how many sounds a name has","pick the name for a described symbol","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.CREATI.RHYTHM.RHQUAL', 'CREA.G4.CREATI.RHYTHM', 'creative_arts', 4, 'Name the qualities of a good rhythmic pattern', ARRAY['CREA.G4.CREATI.RHYTHM.c']::text[], 'The child says a good rhythmic pattern mixes different note values (variation), repeats part of its pattern so it can be remembered (repetition) and ends on a long note, and does not say it must be fast, long or all the same note. This is the knowledge half of outcomes c and d; composing is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G4.RUBRIC.1.1), never as a phone question: d) compose a rhythmic pattern involving a crochet, a pair of quavers and their rests.', '["pick the quality a pattern has","pick the pattern that ends well","say why a quality makes a pattern better","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.CREATI.RHYTHM.LETTERING', 'CREA.G4.CREATI.RHYTHM', 'creative_arts', 4, 'Tell the ascenders and descenders in free hand lettering', ARRAY['CREA.G4.CREATI.RHYTHM.b']::text[], 'The child says an ascender is the part of a letter that goes up above the main body (b, d, h, k, l), a descender is the part that goes down below the line (g, j, p, q, y), and letters such as a, c, e, o and s have neither. This is the knowledge half of outcome b; lettering is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G4.RUBRIC.1.1), never as a phone question: b) write the French rhythm taa and ta-te, names using free hand lettering.', '["say whether a letter goes up or down","sort letters into ascenders and descenders","say what the middle of a word looks like","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.CREATI.MELODY.SOLFA', 'CREA.G4.CREATI.MELODY', 'creative_arts', 4, 'Put the sol-fa syllables d, r and m in order of pitch', ARRAY['CREA.G4.CREATI.MELODY.a']::text[], 'The child puts d r m in order from the lowest sound to the highest (d lowest, m highest), says them backwards for a melody going down, and knows d is the home note a melody likes to end on. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the syllable that is higher or lower","say which syllable is lowest or highest","put the syllables in order","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.CREATI.MELODY.SIGNS', 'CREA.G4.CREATI.MELODY', 'creative_arts', 4, 'Interpret the Kodaly hand signs for d, r and m', ARRAY['CREA.G4.CREATI.MELODY.b']::text[], 'The child says d is a closed fist held low (near the waist), r is a hand sloping upward, m is a flat hand with the palm down held higher (near the chest), and that the hand is held higher as the pitch gets higher. Shapes, signs and holes are described in words, because the phone question has no staff or picture. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say which syllable a described sign shows","say how a syllable''s sign looks","say how the height of the hand changes","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.CREATI.MELODY.MELQUAL', 'CREA.G4.CREATI.MELODY', 'creative_arts', 4, 'Name the qualities of a good melody', ARRAY['CREA.G4.CREATI.MELODY.c']::text[], 'The child says a good short melody moves by step to the next syllable (stepwise motion), changes the syllables and the lengths of the sounds (variation) and ends on d, and does not say it must use one syllable only, be very long or end on any syllable. This is the knowledge half of outcome c; composing is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G4.RUBRIC.1.1), never as a phone question: d) create short melodies using the sol-fa syllables d, r and m.', '["pick the quality a melody has","pick the melody that ends well","say why a quality makes a melody better","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.CREATI.MELODY.CLAY', 'CREA.G4.CREATI.MELODY', 'creative_arts', 4, 'Put the steps of modelling with slabs and coils in order', ARRAY['CREA.G4.CREATI.MELODY.e']::text[], 'The child puts the steps in order: collect clean clay from the local environment, remove stones, knead it, roll it flat into a slab and cut three rectangles of different sizes, roll thin snakes (coils) and shape the letters d, r and m, then attach them to the slabs with a little water. The child says a coil is a rolled clay snake, keeps unused clay damp under a cloth, and washes hands after. This is the knowledge half of outcome e; modelling is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G4.RUBRIC.1.1), never as a phone question: e) model clay slabs with sol-fa syllables using coil and slab techniques.', '["put the steps in order","say what a slab or a coil is","say how to keep the clay safe to use","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.PERFOR.ATHLETICS.STARTS', 'CREA.G4.PERFOR.ATHLETICS', 'creative_arts', 4, 'Describe the medium and elongated sprint starts', ARRAY['CREA.G4.PERFOR.ATHLETICS.a']::text[], 'The child puts the commands in order (On your marks, Set, Go), says the feet are placed further apart in an elongated start than in a medium start, says at Set the hips are raised and the weight goes forward, and keeps eyes down and ahead at the start. This is the knowledge half of outcome a; running is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say what is different between two starts","put the start commands in order","say what the body does at set","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.PERFOR.ATHLETICS.SPRINT', 'CREA.G4.PERFOR.ATHLETICS', 'creative_arts', 4, 'Describe good sprinting technique', ARRAY['CREA.G4.PERFOR.ATHLETICS.a']::text[], 'The child says a sprinter leans forward at the start then runs upright, lifts the knees, bends the arms and swings them forward and back (not across the body), runs on the balls of the feet, looks ahead and runs through the finish line without slowing. This is the knowledge half of outcomes a and b; sprinting is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G4.RUBRIC.2.1), never as a phone question: b) perform the sprint starts and sprinting techniques for skill development.', '["pick the arm or leg action of a good sprint","say where the eyes look","say what to do at the finish line","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.PERFOR.ATHLETICS.FLAG', 'CREA.G4.PERFOR.ATHLETICS', 'creative_arts', 4, 'Name the colours and the meaning of the Kenyan flag', ARRAY['CREA.G4.PERFOR.ATHLETICS.c', 'CREA.G4.PERFOR.ATHLETICS.d']::text[], 'The child puts the colours in order from the top (black, red, green, with thin white lines between), gives the meaning of each (black for the people, red for the blood shed for freedom, green for the land and its wealth, white for peace), says the shield and two crossed spears are in the middle, and that flying the flag shows love of country and unity. This is the knowledge half of outcomes c and d; painting is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G4.RUBRIC.2.1), never as a phone question: c) paint the Kenyan flag for an athletic event.', '["pick the colour for a meaning","put the colours in order from the top","say why the flag is flown","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.PERFOR.GYMNASTICS.BALANCES', 'CREA.G4.PERFOR.GYMNASTICS', 'creative_arts', 4, 'Explain the crab balance and the side roll', ARRAY['CREA.G4.PERFOR.GYMNASTICS.a']::text[], 'The child says the crab balance is held with hands and feet on the mat, tummy facing up and hips lifted, for a count of three, and that the side roll starts lying straight on the mat with arms stretched above the head and legs together, rolling sideways without bending, not over the head. This is the knowledge half of outcome a; performing is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G4.RUBRIC.2.1), never as a phone question: b) perform the crab balance for skill acquisition; c) execute the side roll for skill acquisition.', '["describe the crab balance","describe the side roll","say what the body looks like in each","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.PERFOR.GYMNASTICS.GYMSAFE', 'CREA.G4.PERFOR.GYMNASTICS', 'creative_arts', 4, 'Keep safe when doing gymnastics', ARRAY['CREA.G4.PERFOR.GYMNASTICS.a']::text[], 'The child says gymnastics is done on a mat or soft ground cleared of stones, after a warm-up, taking turns with space around, with no sharp things such as rings or hairpins, and stops if a part hurts and tells the teacher, and gives the reason for each rule. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the safe action before a move","say why a safety rule matters","say what to do in a gym story","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.PERFOR.SONGS.TYPES', 'CREA.G4.PERFOR.SONGS', 'creative_arts', 4, 'Tell sacred, patriotic and topical songs apart', ARRAY['CREA.G4.PERFOR.SONGS.a']::text[], 'The child says a sacred song is about worship or God, a patriotic song is about loving and serving the country (the national anthem is one), a topical song is about an issue people are talking about now (hygiene, road safety, looking after trees), and does not call every religious-sounding song patriotic. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G4.RUBRIC.2.1), never as a phone question: a) sing different types of songs applying performance techniques.', '["pick the type of a song from its words","pick the occasion for a type","say what each type is about","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.PERFOR.SONGS.PERFTERMS', 'CREA.G4.PERFOR.SONGS', 'creative_arts', 4, 'Use the words pitch, tempo, dynamics and unison for singing', ARRAY['CREA.G4.PERFOR.SONGS.a']::text[], 'The child says pitch is how high or low a sound is, tempo is the speed of the song, dynamics are how loud or soft it is sung, unison is everyone singing the same notes together, diction is saying the words clearly, and that facial expression and gestures match the mood of the song. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say what a singing word means","pick the word for a described singing","say what a good singer does","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.PERFOR.SONGS.EAC', 'CREA.G4.PERFOR.SONGS', 'creative_arts', 4, 'Say how the East African Community anthem is sung and what it is about', ARRAY['CREA.G4.PERFOR.SONGS.b']::text[], 'The child says the East African Community anthem is sung in unison (everyone together on the same notes), standing straight and still with respect, that the words call on God to bless East Africa and ask for peace and unity, and that it is sung at East African Community events. This is the knowledge half of outcome b; singing is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G4.RUBRIC.2.1), never as a phone question: b) perform the East African Community Anthem in unison.', '["say what unison means for the anthem","say how to stand and behave","say what the anthem is about","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.PERFOR.SONGS.FOLKTYPES', 'CREA.G4.PERFOR.SONGS', 'creative_arts', 4, 'Classify Kenyan folk songs by the occasion they are sung on', ARRAY['CREA.G4.PERFOR.SONGS.c']::text[], 'The child classifies a folk song by its occasion: a work song is sung while farming, grinding or harvesting, a funeral song is sung to mourn, a naming song welcomes a new baby, an initiation song marks a child growing up, a marriage song is sung at a wedding and a worship song praises God, and knows each community has its own songs. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G4.RUBRIC.2.1), never as a phone question: d) perform an indigenous Kenyan folk song applying performance techniques.', '["pick the type of folk song for an occasion","pick the occasion for a type","say why a community sings it","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.PERFOR.PHOTOGRAPHY.DEVICES', 'CREA.G4.PERFOR.PHOTOGRAPHY', 'creative_arts', 4, 'Identify digital devices for photography and use them well', ARRAY['CREA.G4.PERFOR.PHOTOGRAPHY.a']::text[], 'The child names a phone, a digital camera and a tablet as digital devices that take photographs, and says a television, a radio and a calculator do not, holds the device with both hands, keeps the lens clean and dry, and asks permission before photographing a person. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the device that takes photographs","pick the careful action with a device","say what to do before photographing someone","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.PERFOR.PHOTOGRAPHY.ELEMENTS', 'CREA.G4.PERFOR.PHOTOGRAPHY', 'creative_arts', 4, 'Say what good light and a centre of interest are in a photograph', ARRAY['CREA.G4.PERFOR.PHOTOGRAPHY.b']::text[], 'The child says the centre of interest is the main thing the photograph is about and it should be clear and not too small, good light falls on the subject from the side or front (the photographer keeps the sun behind them, not behind the subject), and a person in shadow with a bright sky behind looks dark. This is the knowledge half of outcome b; taking photographs is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G4.RUBRIC.2.1), never as a phone question: c) take photographs using digital devices.', '["say what the centre of interest is","say where the light should come from","pick the better photograph from a description","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.PERFOR.DESCANT_RECORDER.RECPARTS', 'CREA.G4.PERFOR.DESCANT_RECORDER', 'creative_arts', 4, 'Name the parts of a descant recorder and what each does', ARRAY['CREA.G4.PERFOR.DESCANT_RECORDER.a']::text[], 'The child names the head joint (the top part with the mouthpiece where the player blows), the middle joint (with the finger holes) and the foot joint (the lowest part, with the last holes), and says covering holes changes the note. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the part from its job","say where the player blows","say where the finger holes are","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.PERFOR.DESCANT_RECORDER.CARE', 'CREA.G4.PERFOR.DESCANT_RECORDER', 'creative_arts', 4, 'Care for a descant recorder: hygiene, handling and storage', ARRAY['CREA.G4.PERFOR.DESCANT_RECORDER.b']::text[], 'The child washes hands before playing, wipes or cleans the mouthpiece with clean warm (not hot) water and dries it, never shares a mouthpiece without cleaning it, does not drop it or bite it, and stores it dry in a bag or case away from the sun and heat, and gives the reason for each step. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right way to clean or store it","say why a care step matters","choose the careful action in a story","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.PERFOR.DESCANT_RECORDER.NOTES', 'CREA.G4.PERFOR.DESCANT_RECORDER', 'creative_arts', 4, 'Order the recorder notes B, A and G and say which holes each covers', ARRAY['CREA.G4.PERFOR.DESCANT_RECORDER.c', 'CREA.G4.PERFOR.DESCANT_RECORDER.d']::text[], 'The child puts the notes in order from the lowest, G, then A, then B, says B covers the thumb hole and one finger of the left hand, A the thumb and two fingers and G the thumb and three fingers, and that covering more holes gives a lower note. This is the knowledge half of outcomes c and d; playing is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G4.RUBRIC.2.1), never as a phone question: c) play notes B A and G on a descant recorder using appropriate playing techniques; d) play simple melodies based on notes B A and G on the descant recorder.', '["put the notes in order of pitch","say how many fingers B, A or G needs","say whether a note is higher or lower","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.PERFOR.DESCANT_RECORDER.TECHNIQUE', 'CREA.G4.PERFOR.DESCANT_RECORDER', 'creative_arts', 4, 'Describe good recorder technique: posture, fingering and blowing', ARRAY['CREA.G4.PERFOR.DESCANT_RECORDER.c']::text[], 'The child says to sit or stand tall with the recorder held in front, left hand above right, to cover each hole fully with the soft pad of the finger (not the tip), to blow gently and steadily as if saying too, and that blowing hard makes a harsh squeak. This is the knowledge half of outcome c; playing is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say how to sit or stand","say how to cover a hole","say how hard to blow","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.PERFOR.SWIMMING.SAFETY', 'CREA.G4.PERFOR.SWIMMING', 'creative_arts', 4, 'Enter the water feet first and keep safe in and out of the pool', ARRAY['CREA.G4.PERFOR.SWIMMING.a_', 'CREA.G4.PERFOR.SWIMMING.e']::text[], 'The child says the safe way in is feet first from the edge or the steps, in water the teacher says is safe, never diving into shallow water, never going in alone or without a teacher or lifeguard, walking and not running on the pool side, and not pushing others. This is the knowledge half of outcomes a and e; entering the water is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G4.RUBRIC.2.1), never as a phone question: b) play water games in the swimming pool for fun.', '["pick the safe way to enter the water","pick the safe action at the pool","say why a rule matters","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.PERFOR.SWIMMING.FLOAT', 'CREA.G4.PERFOR.SWIMMING', 'creative_arts', 4, 'Describe floating and gliding', ARRAY['CREA.G4.PERFOR.SWIMMING.c_', 'CREA.G4.PERFOR.SWIMMING.d_']::text[], 'The child says in a mushroom float the knees are hugged to the chest with the face in the water, in a back (supine) float the body lies face up with ears in the water, in a front (prone) float the body lies face down and stretched, and a glide is a push from the wall with arms stretched ahead, body straight and legs together. This is the knowledge half of outcomes c and d; swimming is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G4.RUBRIC.2.1), never as a phone question: c) float in water for skill acquisition; d) glide in water for water confidence.', '["pick the float from how the body looks","say how a glide is done","say why staying relaxed helps","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.PERFOR.SWIMMING.ANIMAL', 'CREA.G4.PERFOR.SWIMMING', 'creative_arts', 4, 'Identify indigenous animal games and what they build', ARRAY['CREA.G4.PERFOR.SWIMMING.a_2']::text[], 'The child says animal games copy an animal: the frog jump (squat and leap) builds leg strength, the crab walk (on hands and feet, tummy up) builds arm and shoulder strength, hopping like a bird builds balance, and a hare chase builds speed, and that people played them long ago for fun and fitness. Names vary by community. This is the knowledge half of outcome a_2. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G4.RUBRIC.2.1), never as a phone question: b (second set)) perform different indigenous animal games for skill acquisition; c (second set)) perform indigenous animal games to a musical rhythm for enjoyment.', '["name the animal game from the action","say what a game builds","pick the game that builds a skill","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.CONCEPT', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART', 'creative_arts', 4, 'Say what appreciation of creative art means and how to give kind feedback', ARRAY['CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.a']::text[], 'The child says appreciation means looking or listening carefully to a work and thinking about what is good in it (how it looks, the skill, the message), that good feedback says what is good and gives one idea to improve it in a kind way, and that at an exhibition we do not touch the works, we speak quietly and we respect each maker. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say what appreciation means","pick the kind and helpful comment","pick the right behaviour at an exhibition","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.PORTFOLIO', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART', 'creative_arts', 4, 'Say what a portfolio is and how to make and care for one', ARRAY['CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.b']::text[], 'The child says a portfolio is a folder of a learner''s best works kept to show how they have grown, made from locally available things (cardboard, folded paper, an old file), decorated with coloured paper or fabric, with each work labelled with name and date and kept flat and dry. This is the knowledge half of outcome b; making it is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G4.RUBRIC.3.1), never as a phone question: b) make a portfolio for presenting creative art works.', '["say what a portfolio is for","put the steps of making one in order","pick a local material for it","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.ANTHEM', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART', 'creative_arts', 4, 'Say what the Kenya National Anthem is about and how to behave when it is sung', ARRAY['CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.c']::text[], 'The child says the Kenya National Anthem has three verses and begins in Kiswahili with the words Ee Mungu nguvu yetu, it is a prayer asking God to bless Kenya and to keep peace and unity, we stand straight and still and sing with respect, and it is sung at national days, school assemblies and sports events. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say what the anthem is for","say how many verses it has","pick the right behaviour when it is sung","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.FOLKPERF', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART', 'creative_arts', 4, 'Name the parts of a folk song performance', ARRAY['CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.d']::text[], 'The child names the community the song comes from, its type or occasion, its message, the participants (a soloist who leads, singers who answer, instrumentalists who play) and the instruments, and does not call the whole group the soloist. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the part from a described performance","say who does what","say what the message is","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
