INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.ID', 'CREA.G3.PERFOR.STRING_MUSICAL_INSTRUMEN.d', 'outcome', 'helpful', 'Valuing Kenyan string instruments (Grade 3) is where naming instruments by community began. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
