INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.CLASSIFY', 'CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN.SOUND_DURATION', 'skill', 'essential', 'Hearing long and short sounds (Grade 3) comes before hearing whether an instrument can change pitch. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.DRUMPARTS', 'CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.ID', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.DRUMPARTS', 'CREA.G3.PERFOR.STRING_MUSICAL_INSTRUMEN.STRING_INSTR', 'skill', 'essential', 'Improvising a string instrument (Grade 3) showed that a tight, shaking part makes the sound, as the drum skin does. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.CHARCOAL', 'CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.ID', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.CHARCOAL', 'CREA.G3.CREATI.DRAWING_AND_PAINTING.SHAPES_PICTURE', 'skill', 'essential', 'Drawing with shapes (Grade 3) comes before shading a drawing with charcoal. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.CREATI.NETBALL.PASSES', 'CREA.G3.PERFOR.GALLOPING.GALLOP', 'skill', 'helpful', 'Moving in different directions (Grade 3) is what a player does to get free for a pass. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.CREATI.NETBALL.PASSES', 'CREA.G3.CREATI.PUSHING_AND_PULLING.PUSH_PULL', 'skill', 'essential', 'Pushing (Grade 3) is the action of a chest pass. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.CREATI.NETBALL.MACRAME', 'CREA.G4.CREATI.NETBALL.PASSES', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.CREATI.NETBALL.MACRAME', 'CREA.G3.CREATI.WEAVING.PAPER_WEAVE', 'skill', 'essential', 'Plain paper weaving (Grade 3) is the first craft of passing strands over and under; macramé ties them. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.COLOURS', 'CREA.G3.CREATI.DRAWING_AND_PAINTING.COLOUR_MIXING', 'skill', 'essential', 'Mixing colours by spraying and blowing (Grade 3) shows which colours can be made. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.COLOURS', 'CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_TOOLS', 'skill', 'helpful', 'Naming paints and colouring materials (Grade 1) gives the child the colours this skill sorts. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.MIX', 'CREA.G4.CREATI.PAINTING_AND_MONTAGE.COLOURS', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.MIX', 'CREA.G3.CREATI.DRAWING_AND_PAINTING.COLOUR_MIXING', 'skill', 'essential', 'Identifying colour mixing (Grade 3) is the first step to naming the pair. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.VALUE', 'CREA.G4.CREATI.PAINTING_AND_MONTAGE.MIX', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.VALUE', 'CREA.G3.CREATI.DRAWING_AND_PAINTING.COLOUR_MIXING', 'skill', 'essential', 'Painting a picture (Grade 3) comes before controlling light and dark in it. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.MONTAGE', 'CREA.G3.CREATI.COLLAGE.COLLAGE', 'skill', 'essential', 'Making a collage (Grade 3) is the cut-and-paste skill a montage uses with pictures. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.MONTAGE', 'CREA.G3.CREATI.DRAWING_AND_PAINTING.SHAPES_PICTURE', 'skill', 'helpful', 'Reading the shapes in a picture (Grade 3) is how the child chooses and arranges the cut pictures. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.CREATI.RHYTHM.VALUES', 'CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN.SOUND_DURATION', 'skill', 'essential', 'Grade 3 Creative Activities introduced it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.CREATI.RHYTHM.VALUES', 'MATH.G4.NUMBER.FRACTIONS.b', 'outcome', 'essential', 'Another subject taught it first. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.CREATI.RHYTHM.VALUES', 'MATH.G4.NUMBER.FRACTIONS.FRACTION_OF_WHOLE', 'skill', 'helpful', 'A half as part of a whole (Grade 4 Maths) is what a quaver is of a beat. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
