INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.PERFOR.SWIMMING.FLOAT', 'CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_DANGERS', 'skill', 'essential', 'Knowing the dangers of deep water (Grade 3) is why floating is the first water skill. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.PERFOR.SWIMMING.ANIMAL', 'CREA.G3.PERFOR.GALLOPING.GALLOP', 'skill', 'essential', 'Galloping games (Grade 3) are the movements animal games copy. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.PERFOR.SWIMMING.ANIMAL', 'CREA.G1.PERFOR.SINGING_GAMES_KENYAN_STY.KENYAN_GAMES', 'skill', 'helpful', 'Kenyan singing games (Grade 1) are the first indigenous games with rules, players and parts. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
