INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.CONCEPT', 'ENGL.G4.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_PARTS', 'skill', 'helpful', 'Saying what a story is made of (Grade 4 English) is like saying what an artwork is made of. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
