INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.PORTFOLIO', 'CREA.G3.CREATI.COLLAGE.COLLAGE', 'skill', 'essential', 'Making artworks (Grade 3) gives the pieces a portfolio holds. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.ANTHEM', 'CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_TEXT', 'skill', 'essential', 'Knowing the first stanza (Grade 3) comes before analysing its message. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.ANTHEM', 'CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_OCCASIONS', 'skill', 'essential', 'The occasions and etiquette of the anthem (Grade 3) are the behaviour this skill asks the child to explain. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.FOLKPERF', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.CONCEPT', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.FOLKPERF', 'CREA.G4.PERFOR.SONGS.FOLKTYPES', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.FOLKPERF', 'CREA.G3.PERFOR.ROUNDS.ROUND', 'skill', 'helpful', 'Hearing parts in a round (Grade 3) is the first step to naming parts of a performance. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.ID.M_CA4_PC_STRING_AS_PERC', 'CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.ID', 'Puts a string instrument (nyatiti, orutu) in the percussion group.', '{"question":"Which of these is a percussion instrument?","wrong_answer":"The nyatiti","correct_answer":"The ngoma drum"}'::jsonb, 'The child knows the instrument is indigenous but not how its sound is made.', 'Offer "The nyatiti" next to the right answer and ask the question again in a new context.', 'Ask: do you hit it, pluck it or blow it? Sort five instruments by that one question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.ID.M_CA4_PC_WIND_AS_PERC', 'CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.ID', 'Puts a blown instrument (nzumari, siwa, flute) in the percussion group.', '{"question":"Which of these is a percussion instrument?","wrong_answer":"The nzumari","correct_answer":"The kayamba"}'::jsonb, 'The child sorts by "makes a loud sound" and not by how it is played.', 'Offer "The nzumari" next to the right answer and ask the question again in a new context.', 'Ask who makes the sound: the breath, a plucking finger or a hit?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.ID.M_CA4_PC_KAYAMBA_HIT', 'CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.ID', 'Says the kayamba is played by hitting it with sticks.', '{"question":"How is the kayamba played?","wrong_answer":"It is hit with two sticks","correct_answer":"It is shaken"}'::jsonb, 'The child thinks every percussion instrument is a drum.', 'Offer "It is hit with two sticks" next to the right answer and ask the question again in a new context.', 'Shake a tin of seeds and listen: the seeds hit the walls and make the sound.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.ID.M_CA4_PC_COMMUNITY', 'CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.ID', 'Gives an instrument to the wrong community (the isukuti to the Luo or the kayamba to the Luhya).', '{"question":"The isukuti drums belong mainly to which people?","wrong_answer":"The Luo","correct_answer":"The Luhya"}'::jsonb, 'The child has not met the instrument or the place it comes from.', 'Offer "The Luo" next to the right answer and ask the question again in a new context.', 'Use a map of Kenya and a recording of isukuti to link the sound to the Luhya of western Kenya.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.CLASSIFY.M_CA4_PC_LOUD_MELODIC', 'CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.CLASSIFY', 'Calls a loud instrument melodic and a quiet one non-melodic.', '{"question":"Which of these is a melodic instrument?","wrong_answer":"The loudest drum","correct_answer":"The xylophone"}'::jsonb, 'The child sorts by how strong the sound is.', 'Offer "The loudest drum" next to the right answer and ask the question again in a new context.', 'Play one drum hard and soft: the note does not change. Then play a xylophone bar by bar.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.CLASSIFY.M_CA4_PC_ALL_MELODIC', 'CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.CLASSIFY', 'Says every percussion instrument is melodic because it makes a sound.', '{"question":"Is a kayamba melodic?","wrong_answer":"Yes, every instrument makes a sound","correct_answer":"No, it makes one kind of sound and cannot play a tune"}'::jsonb, 'The child thinks any sound is music with a tune.', 'Offer "Yes, every instrument makes a sound" next to the right answer and ask the question again in a new context.', 'Shake the kayamba and try to hum a tune with it. Then do the same on tuned bars.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.CLASSIFY.M_CA4_PC_NONMEL_MEANS', 'CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.CLASSIFY', 'Thinks non-melodic means it makes no sound or a bad sound.', '{"question":"What does non-melodic mean?","wrong_answer":"It makes a bad sound","correct_answer":"It cannot play different notes to make a tune"}'::jsonb, 'The child reads non- as bad or silent.', 'Offer "It makes a bad sound" next to the right answer and ask the question again in a new context.', 'Play a non-melodic shaker in a rhythm: it sounds good but has one sound.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.DRUMPARTS.M_CA4_PC_SHELL_SOUND', 'CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.DRUMPARTS', 'Says the wooden shell alone makes the sound.', '{"question":"What part of a drum vibrates to make the main sound?","wrong_answer":"The wooden shell","correct_answer":"The skin"}'::jsonb, 'The child sees the biggest part and thinks it must be the sound.', 'Offer "The wooden shell" next to the right answer and ask the question again in a new context.', 'Lay a few grains on the skin and tap it: the grains jump. Touch the shell: it hardly moves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.DRUMPARTS.M_CA4_PC_LOOSE_HIGHER', 'CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.DRUMPARTS', 'Thinks a looser skin gives a higher sound.', '{"question":"A drummer tightens the skin. What happens to the sound?","wrong_answer":"It gets lower","correct_answer":"It gets higher"}'::jsonb, 'The child links loose and tight with big and small, not with pitch.', 'Offer "It gets lower" next to the right answer and ask the question again in a new context.', 'Tap a plastic sheet held loose and then held tight over a bowl.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.DRUMPARTS.M_CA4_PC_BIG_HIGHER', 'CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.DRUMPARTS', 'Thinks a bigger drum gives a higher sound.', '{"question":"Which drum gives the lower sound?","wrong_answer":"The small drum","correct_answer":"The big drum"}'::jsonb, 'The child links big with high, as with loudness.', 'Offer "The small drum" next to the right answer and ask the question again in a new context.', 'Hit a small and a big tin and listen: the big one sounds lower.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.DRUMPARTS.M_CA4_PC_STICK_SOUND', 'CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.DRUMPARTS', 'Says the stick makes the sound, not the skin.', '{"question":"What does the drum stick do?","wrong_answer":"It makes the sound by itself","correct_answer":"It hits the skin so the skin vibrates"}'::jsonb, 'The child sees the stick move and hears the sound together.', 'Offer "It makes the sound by itself" next to the right answer and ask the question again in a new context.', 'Hit the stick on the floor: only a small tap. Hit it on the drum: a big sound.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.CHARCOAL.M_CA4_PC_BURN_AIR', 'CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.CHARCOAL', 'Thinks twigs are burned in open flames until they are ash to make charcoal.', '{"question":"How are the twigs burned to make charcoal sticks?","wrong_answer":"In an open fire until they turn to ash","correct_answer":"With little air, in a closed tin or wrapped, so they turn black but stay in shape"}'::jsonb, 'The child knows burning makes ash and does not know about little air.', 'Offer "In an open fire until they turn to ash" next to the right answer and ask the question again in a new context.', 'Show wood char in a tin with a tight lid: it stays black and in shape because little air gets in.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.CHARCOAL.M_CA4_PC_USE_HOT', 'CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.CHARCOAL', 'Thinks the charcoal sticks can be used as soon as the fire is out.', '{"question":"What must happen before the charcoal is used?","wrong_answer":"Nothing, use it at once","correct_answer":"It must cool fully"}'::jsonb, 'The child sees black sticks and thinks they are ready.', 'Offer "Nothing, use it at once" next to the right answer and ask the question again in a new context.', 'Say: hot charcoal burns the skin and stays hot inside for a long time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.CHARCOAL.M_CA4_PC_SMUDGE_ERASE', 'CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.CHARCOAL', 'Thinks smudging is rubbing the drawing out to remove mistakes.', '{"question":"What does smudging do in a charcoal drawing?","wrong_answer":"It removes the drawing","correct_answer":"It spreads the charcoal to make soft light and dark areas"}'::jsonb, 'The child thinks rubbing always means rubbing out.', 'Offer "It removes the drawing" next to the right answer and ask the question again in a new context.', 'Draw a dark patch and rub it with a finger: it spreads into a soft shade.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.CHARCOAL.M_CA4_PC_LIGHT_HARD', 'CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.CHARCOAL', 'Thinks pressing harder makes a lighter shade.', '{"question":"How do you make a darker area with charcoal?","wrong_answer":"Press more lightly","correct_answer":"Press harder or add more layers"}'::jsonb, 'The child links gentle with dark, as with soft sounds.', 'Offer "Press more lightly" next to the right answer and ask the question again in a new context.', 'Make three strokes with light, medium and hard pressure and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.CLASSIFY.M_CA4_PC_SHAKER_MELODIC', 'CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.CLASSIFY', 'Calls the kayamba melodic because it is played in time with a song.', '{"question":"Is the kayamba melodic or non-melodic?","wrong_answer":"melodic, it plays with the song","correct_answer":"non-melodic"}'::jsonb, 'The child thinks anything that plays along with a tune is playing the tune.', 'Offer "melodic, it plays with the song" next to the right answer and ask the question again in a new context.', 'Shake the kayamba softly and loudly: ask if the note goes up or down. It never does.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.NETBALL.PASSES.M_CA4_NB_CHEST_BOUNCE', 'CREA.G4.CREATI.NETBALL.PASSES', 'Says a chest pass is thrown from the head.', '{"question":"Where does a chest pass start?","wrong_answer":"From above the head","correct_answer":"From the chest"}'::jsonb, 'The child mixes the chest pass with the overhead pass.', 'Offer "From above the head" next to the right answer and ask the question again in a new context.', 'Hold the ball at the chest, push out and say chest. Lift above the head and say over.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.NETBALL.PASSES.M_CA4_NB_ONE_HAND', 'CREA.G4.CREATI.NETBALL.PASSES', 'Thinks netball catches and passes are done with one hand.', '{"question":"How should a netball pass or catch be done?","wrong_answer":"With one hand","correct_answer":"With two hands"}'::jsonb, 'The child copies the one-handed throws of other sports.', 'Offer "With one hand" next to the right answer and ask the question again in a new context.', 'Try catching a ball with one hand and with two hands and see which is steadier.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.NETBALL.PASSES.M_CA4_NB_EYES_AWAY', 'CREA.G4.CREATI.NETBALL.PASSES', 'Thinks the catcher should look away from the ball.', '{"question":"What should the catcher look at?","wrong_answer":"At the ground","correct_answer":"At the ball"}'::jsonb, 'The child is afraid of the ball and looks away.', 'Offer "At the ground" next to the right answer and ask the question again in a new context.', 'Roll a soft ball and catch it, first looking at it and then looking away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.NETBALL.PASSES.M_CA4_NB_STIFF_ARMS', 'CREA.G4.CREATI.NETBALL.PASSES', 'Thinks the arms should stay stiff to catch the ball.', '{"question":"How do the arms catch a fast ball?","wrong_answer":"Stiff and straight","correct_answer":"They reach out, then bend to bring the ball in"}'::jsonb, 'The child tries to stop the ball like a wall.', 'Offer "Stiff and straight" next to the right answer and ask the question again in a new context.', 'Catch a soft ball with straight arms and with bending arms.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.NETBALL.MACRAME.M_CA4_NB_MAC_SEW', 'CREA.G4.CREATI.NETBALL.MACRAME', 'Says macramé is made by sewing or gluing.', '{"question":"How is a macramé ball made?","wrong_answer":"By sewing the strings","correct_answer":"By tying knots in strings"}'::jsonb, 'The child thinks all craft needs a needle or glue.', 'Offer "By sewing the strings" next to the right answer and ask the question again in a new context.', 'Tie two strings in an overhand knot and show it holds with no needle or glue.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.NETBALL.MACRAME.M_CA4_NB_MAC_LOOSE', 'CREA.G4.CREATI.NETBALL.MACRAME', 'Leaves the knots loose.', '{"question":"What should be done to each overhand knot?","wrong_answer":"Leave it loose","correct_answer":"Pull it tight"}'::jsonb, 'The child ties the shape and does not finish the knot.', 'Offer "Leave it loose" next to the right answer and ask the question again in a new context.', 'Make one tight and one loose knot, pull both and see which holds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.NETBALL.MACRAME.M_CA4_NB_MAC_HARD_CORE', 'CREA.G4.CREATI.NETBALL.MACRAME', 'Thinks the ball needs a hard stone inside.', '{"question":"What can be put inside a macramé ball?","wrong_answer":"A heavy stone","correct_answer":"Old cloth or paper packed tight"}'::jsonb, 'The child thinks a ball must be heavy to go far.', 'Offer "A heavy stone" next to the right answer and ask the question again in a new context.', 'Say: a netball is light. A stone could hurt a friend.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.NETBALL.MACRAME.M_CA4_NB_MAC_FIRM_LOOSE', 'CREA.G4.CREATI.NETBALL.MACRAME', 'Leaves knots loose so that they look neat and are quick to tie.', '{"question":"Why must macramé knots be pulled tight?","wrong_answer":"so they look nice only","correct_answer":"so the ball keeps its shape and does not come apart"}'::jsonb, 'The child sees knots as decoration and not as what holds the ball together.', 'Offer "so they look nice only" next to the right answer and ask the question again in a new context.', 'Shake a loosely knotted strip and a tight one; see which comes apart.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.COLOURS.M_CA4_PM_GREEN_PRIMARY', 'CREA.G4.CREATI.PAINTING_AND_MONTAGE.COLOURS', 'Says green is a primary colour because it is common in nature.', '{"question":"Which of these is a primary colour?","wrong_answer":"Green","correct_answer":"Blue"}'::jsonb, 'The child counts colours that are easy to see.', 'Offer "Green" next to the right answer and ask the question again in a new context.', 'Mix blue and yellow paint and get green: a colour that can be mixed is not primary.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.COLOURS.M_CA4_PM_BLACK_PRIMARY', 'CREA.G4.CREATI.PAINTING_AND_MONTAGE.COLOURS', 'Says black or white is a primary colour.', '{"question":"Which of these is a primary colour?","wrong_answer":"Black","correct_answer":"Red"}'::jsonb, 'The child thinks the main paints in the box are the primary colours.', 'Offer "Black" next to the right answer and ask the question again in a new context.', 'Say: black and white change tone but are not on the colour wheel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.COLOURS.M_CA4_PM_ORANGE_PRIMARY', 'CREA.G4.CREATI.PAINTING_AND_MONTAGE.COLOURS', 'Says orange is a primary colour.', '{"question":"Which of these is a secondary colour?","wrong_answer":"Yellow","correct_answer":"Orange"}'::jsonb, 'The child does not know how orange is made.', 'Offer "Yellow" next to the right answer and ask the question again in a new context.', 'Mix red and yellow to make orange and say: made by mixing, so secondary.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.MIX.M_CA4_PM_RED_BLUE_GREEN', 'CREA.G4.CREATI.PAINTING_AND_MONTAGE.MIX', 'Says red and blue make green.', '{"question":"Which two colours make purple?","wrong_answer":"Yellow and blue","correct_answer":"Red and blue"}'::jsonb, 'The child mixes up the three pairs.', 'Offer "Yellow and blue" next to the right answer and ask the question again in a new context.', 'Mix each pair on paper and write the result: red and blue gives purple.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.MIX.M_CA4_PM_RED_YELLOW_PURPLE', 'CREA.G4.CREATI.PAINTING_AND_MONTAGE.MIX', 'Says red and yellow make purple or green.', '{"question":"What do red and yellow make?","wrong_answer":"Purple","correct_answer":"Orange"}'::jsonb, 'The child has not mixed the pair.', 'Offer "Purple" next to the right answer and ask the question again in a new context.', 'Mix red and yellow paint and watch orange appear.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.MIX.M_CA4_PM_YELLOW_BLUE_ORANGE', 'CREA.G4.CREATI.PAINTING_AND_MONTAGE.MIX', 'Says blue and yellow make orange.', '{"question":"What do blue and yellow make?","wrong_answer":"Orange","correct_answer":"Green"}'::jsonb, 'The child mixes up the secondary colours.', 'Offer "Orange" next to the right answer and ask the question again in a new context.', 'Mix blue and yellow paint and watch the leaf colour appear.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.VALUE.M_CA4_PM_BLACK_LIGHTER', 'CREA.G4.CREATI.PAINTING_AND_MONTAGE.VALUE', 'Says adding black makes a colour lighter.', '{"question":"A painter adds black to green. What happens?","wrong_answer":"It gets lighter","correct_answer":"It gets darker"}'::jsonb, 'The child thinks any added colour brightens.', 'Offer "It gets lighter" next to the right answer and ask the question again in a new context.', 'Add a little black and then a little white to green paint on paper and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.VALUE.M_CA4_PM_VALUE_NAME', 'CREA.G4.CREATI.PAINTING_AND_MONTAGE.VALUE', 'Thinks colour value means the name or price of the colour.', '{"question":"What does colour value mean?","wrong_answer":"The name of the colour","correct_answer":"How light or dark the colour is"}'::jsonb, 'The child knows value only as price.', 'Offer "The name of the colour" next to the right answer and ask the question again in a new context.', 'Show light blue and dark blue: same colour name, different value.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.VALUE.M_CA4_PM_WHITE_DULL', 'CREA.G4.CREATI.PAINTING_AND_MONTAGE.VALUE', 'Thinks adding white makes a new, different colour and not a lighter one.', '{"question":"What does adding white to orange make?","wrong_answer":"A different colour with a new name","correct_answer":"A lighter tone of orange"}'::jsonb, 'The child sees a paler colour and thinks it is new.', 'Offer "A different colour with a new name" next to the right answer and ask the question again in a new context.', 'Make a strip from orange to light orange and ask: is it still orange?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.VALUE.M_CA4_PM_SCALE_ORDER', 'CREA.G4.CREATI.PAINTING_AND_MONTAGE.VALUE', 'Puts the value scale strip in the wrong order (dark in the middle, or mixed).', '{"question":"A value strip goes from light to dark. Which is in the right order?","wrong_answer":"Dark, light, dark","correct_answer":"Light, medium, dark"}'::jsonb, 'The child puts the strip together without checking the change of tone.', 'Offer "Dark, light, dark" next to the right answer and ask the question again in a new context.', 'Cut the strip into steps and arrange it from the lightest to the darkest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.MONTAGE.M_CA4_PM_MONT_PAINT', 'CREA.G4.CREATI.PAINTING_AND_MONTAGE.MONTAGE', 'Says a montage is painted with a brush.', '{"question":"How is a montage made?","wrong_answer":"By painting with a brush","correct_answer":"By cutting out pictures and pasting them together"}'::jsonb, 'The child mixes montage up with painting.', 'Offer "By painting with a brush" next to the right answer and ask the question again in a new context.', 'Bring old magazines and cut and paste a small picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.MONTAGE.M_CA4_PM_MONT_GAPS', 'CREA.G4.CREATI.PAINTING_AND_MONTAGE.MONTAGE', 'Says pieces must not touch or overlap.', '{"question":"In a montage the pieces should...","wrong_answer":"Stay far apart with gaps","correct_answer":"Overlap so no gaps show"}'::jsonb, 'The child separates pieces like in a collage of objects.', 'Offer "Stay far apart with gaps" next to the right answer and ask the question again in a new context.', 'Place the pieces apart and then overlapping and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.MONTAGE.M_CA4_PM_MONT_RANDOM', 'CREA.G4.CREATI.PAINTING_AND_MONTAGE.MONTAGE', 'Thinks the pictures can be about any subject.', '{"question":"A montage has the theme \"ball games\". Which picture belongs?","wrong_answer":"A picture of a bus","correct_answer":"A picture of children playing netball"}'::jsonb, 'The child pastes any picture.', 'Offer "A picture of a bus" next to the right answer and ask the question again in a new context.', 'Ask: does the picture tell about the theme?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.MONTAGE.M_CA4_PM_MONT_MESSY', 'CREA.G4.CREATI.PAINTING_AND_MONTAGE.MONTAGE', 'Thinks neatness does not matter in a montage.', '{"question":"Which makes a montage neat?","wrong_answer":"Glue showing and rough edges","correct_answer":"Clean edges and little glue showing"}'::jsonb, 'The child focuses on finishing quickly.', 'Offer "Glue showing and rough edges" next to the right answer and ask the question again in a new context.', 'Compare a neat and a messy montage side by side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.COLOURS.M_CA4_PM_BROWN_SECONDARY', 'CREA.G4.CREATI.PAINTING_AND_MONTAGE.COLOURS', 'Calls brown a secondary colour because it is mixed.', '{"question":"Is brown a secondary colour?","wrong_answer":"yes","correct_answer":"no; the secondary colours are orange, green and purple"}'::jsonb, 'The child knows secondaries are mixed and thinks every mixed colour is one.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Show that brown needs all three primaries; a secondary is exactly two primaries.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.PAINTING_AND_MONTAGE.MIX.M_CA4_PM_MIX_WHITE', 'CREA.G4.CREATI.PAINTING_AND_MONTAGE.MIX', 'Thinks adding white to red makes a new secondary colour.', '{"question":"Red and white are mixed. What do you get?","wrong_answer":"orange","correct_answer":"a lighter red (pink)"}'::jsonb, 'White changes the paint, so the child thinks it makes a new colour.', 'Offer "orange" next to the right answer and ask the question again in a new context.', 'Mix red and white: it is still red, only lighter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.RHYTHM.VALUES.M_CA4_RH_QUAVER_LONGER', 'CREA.G4.CREATI.RHYTHM.VALUES', 'Thinks a quaver is longer than a crotchet because it has two sounds.', '{"question":"How many beats do a pair of quavers last together?","wrong_answer":"Two beats","correct_answer":"One beat"}'::jsonb, 'The child counts the sounds and not the beats.', 'Offer "Two beats" next to the right answer and ask the question again in a new context.', 'Clap one crotchet, then clap two quick claps in the same beat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.RHYTHM.VALUES.M_CA4_RH_REST_SKIP', 'CREA.G4.CREATI.RHYTHM.VALUES', 'Thinks a rest means skip the beat and does not count it.', '{"question":"A crotchet rest comes in a pattern. What do you do?","wrong_answer":"Skip it and go on","correct_answer":"Stay silent for one beat"}'::jsonb, 'The child thinks a rest is nothing.', 'Offer "Skip it and go on" next to the right answer and ask the question again in a new context.', 'Clap taa, rest, taa while counting 1 2 3 out loud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.RHYTHM.VALUES.M_CA4_RH_REST_SOUND', 'CREA.G4.CREATI.RHYTHM.VALUES', 'Thinks a rest is a note that is sounded.', '{"question":"What do you do at a rest?","wrong_answer":"Make a sound","correct_answer":"Make no sound"}'::jsonb, 'The child sees the rest as another symbol to play.', 'Offer "Make a sound" next to the right answer and ask the question again in a new context.', 'Clap the pattern and hold open hands at the rest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.RHYTHM.VALUES.M_CA4_RH_QUAVER_REST_FULL', 'CREA.G4.CREATI.RHYTHM.VALUES', 'Says a quaver rest is one whole beat.', '{"question":"How long is a quaver rest?","wrong_answer":"One whole beat","correct_answer":"Half a beat"}'::jsonb, 'The child mixes up the quaver and the crotchet rest.', 'Offer "One whole beat" next to the right answer and ask the question again in a new context.', 'Match each rest to the note of the same length.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.RHYTHM.NAMES.M_CA4_RH_TATE_TWO_BEATS', 'CREA.G4.CREATI.RHYTHM.NAMES', 'Says ta-te lasts two beats.', '{"question":"How long does ta-te last?","wrong_answer":"Two beats","correct_answer":"One beat with two sounds"}'::jsonb, 'The child counts the two sounds as two beats.', 'Offer "Two beats" next to the right answer and ask the question again in a new context.', 'Say ta-te as you tap one beat once.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.RHYTHM.NAMES.M_CA4_RH_TAA_PAIR', 'CREA.G4.CREATI.RHYTHM.NAMES', 'Says taa is the name for a pair of quavers.', '{"question":"Which name is for a crotchet?","wrong_answer":"Ta-te","correct_answer":"Taa"}'::jsonb, 'The child mixes the two names.', 'Offer "Ta-te" next to the right answer and ask the question again in a new context.', 'Say taa slowly and ta-te quickly and tap the beats.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.RHYTHM.NAMES.M_CA4_RH_REST_TAA', 'CREA.G4.CREATI.RHYTHM.NAMES', 'Says a rest is also said as taa.', '{"question":"What do you say aloud at a rest?","wrong_answer":"Taa","correct_answer":"Nothing, it is silent"}'::jsonb, 'The child says a name for every symbol.', 'Offer "Taa" next to the right answer and ask the question again in a new context.', 'Chant taa, rest, taa and hold the rest in silence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.RHYTHM.RHQUAL.M_CA4_RH_ALL_SAME', 'CREA.G4.CREATI.RHYTHM.RHQUAL', 'Thinks a good rhythm uses the same note value all through.', '{"question":"Which pattern has variation?","wrong_answer":"Taa taa taa taa","correct_answer":"Taa ta-te taa taa"}'::jsonb, 'The child thinks steady means good.', 'Offer "Taa taa taa taa" next to the right answer and ask the question again in a new context.', 'Clap both and ask which is more interesting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.RHYTHM.RHQUAL.M_CA4_RH_NO_REPEAT', 'CREA.G4.CREATI.RHYTHM.RHQUAL', 'Thinks a good pattern never repeats.', '{"question":"What does repetition do in a pattern?","wrong_answer":"It makes the pattern boring and wrong","correct_answer":"It makes a part easy to remember"}'::jsonb, 'The child thinks every bar must be new.', 'Offer "It makes the pattern boring and wrong" next to the right answer and ask the question again in a new context.', 'Clap a tune that repeats a short part and ask if it is easy to remember.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.RHYTHM.RHQUAL.M_CA4_RH_END_SHORT', 'CREA.G4.CREATI.RHYTHM.RHQUAL', 'Thinks a good pattern ends on a short note.', '{"question":"A good rhythmic pattern ends on...","wrong_answer":"A short note","correct_answer":"A long note"}'::jsonb, 'The child thinks the end should be quick.', 'Offer "A short note" next to the right answer and ask the question again in a new context.', 'Clap one ending on a short sound and one on a long sound.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.RHYTHM.LETTERING.M_CA4_RH_G_ASC', 'CREA.G4.CREATI.RHYTHM.LETTERING', 'Says g, p or y have ascenders.', '{"question":"Which letter has a descender?","wrong_answer":"d","correct_answer":"g"}'::jsonb, 'The child looks at the tail and thinks it goes up.', 'Offer "d" next to the right answer and ask the question again in a new context.', 'Write the letters on a ruled line and see which go below it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.RHYTHM.LETTERING.M_CA4_RH_B_DESC', 'CREA.G4.CREATI.RHYTHM.LETTERING', 'Says b, d, h, k or l have descenders.', '{"question":"Which letter has an ascender?","wrong_answer":"p","correct_answer":"b"}'::jsonb, 'The child mixes ascender and descender.', 'Offer "p" next to the right answer and ask the question again in a new context.', 'Draw a line and write b above and p below it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.RHYTHM.LETTERING.M_CA4_RH_ALL_ASC', 'CREA.G4.CREATI.RHYTHM.LETTERING', 'Says every letter has an ascender or descender.', '{"question":"Which letter has neither?","wrong_answer":"k","correct_answer":"a"}'::jsonb, 'The child thinks every letter sticks out.', 'Offer "k" next to the right answer and ask the question again in a new context.', 'Write the word "ace" and look for letters that go neither up nor down.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.RHYTHM.NAMES.M_CA4_RH_SA_REST', 'CREA.G4.CREATI.RHYTHM.NAMES', 'Says "taa" for a crotchet rest, reading every symbol as a sound.', '{"question":"What do you say for a crotchet rest?","wrong_answer":"taa","correct_answer":"nothing: say \"sa\" in your head or show silence for one beat"}'::jsonb, 'The child reads every symbol on the line as a sound to say.', 'Offer "taa" next to the right answer and ask the question again in a new context.', 'Clap a pattern and hold hands apart for the rest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.RHYTHM.RHQUAL.M_CA4_RH_TOO_LONG', 'CREA.G4.CREATI.RHYTHM.RHQUAL', 'Thinks a longer pattern is always a better pattern.', '{"question":"Which is better: a pattern that repeats a clear idea, or one that is very long and never repeats?","wrong_answer":"the very long one","correct_answer":"the one that repeats a clear idea"}'::jsonb, 'Length feels like effort, so the child counts it as quality.', 'Offer "the very long one" next to the right answer and ask the question again in a new context.', 'Clap both; ask which one the class can remember.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.RHYTHM.LETTERING.M_CA4_RH_SIZES_MIX', 'CREA.G4.CREATI.RHYTHM.LETTERING', 'Writes small letters as tall as capital letters in free hand lettering.', '{"question":"In free hand lettering, is \"a\" as tall as \"T\"?","wrong_answer":"yes","correct_answer":"no; small letters stay between the middle lines"}'::jsonb, 'The child copies letters one at a time without guide lines.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Rule four guide lines and write a, t, g on them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.MELODY.SOLFA.M_CA4_ML_M_LOWEST', 'CREA.G4.CREATI.MELODY.SOLFA', 'Thinks m is the lowest sound.', '{"question":"Which syllable is the lowest?","wrong_answer":"m","correct_answer":"d"}'::jsonb, 'The child thinks the last letter of the alphabet order is lowest or gets confused.', 'Offer "m" next to the right answer and ask the question again in a new context.', 'Sing d r m going up and show with the hand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.MELODY.SOLFA.M_CA4_ML_D_HIGHEST', 'CREA.G4.CREATI.MELODY.SOLFA', 'Thinks d is the highest because it is sung first.', '{"question":"Which syllable is the highest?","wrong_answer":"d","correct_answer":"m"}'::jsonb, 'The child links first with highest.', 'Offer "d" next to the right answer and ask the question again in a new context.', 'Sing d first and then climb to m.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.MELODY.SOLFA.M_CA4_ML_ORDER_MIX', 'CREA.G4.CREATI.MELODY.SOLFA', 'Puts r first or last in the order.', '{"question":"Which is the right order from low to high?","wrong_answer":"r d m","correct_answer":"d r m"}'::jsonb, 'The child has not sung the steps in order.', 'Offer "r d m" next to the right answer and ask the question again in a new context.', 'Sing d r m slowly and point to steps on a stair.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.MELODY.SOLFA.M_CA4_ML_END_ANY', 'CREA.G4.CREATI.MELODY.SOLFA', 'Thinks a melody may end on any syllable as well as on d.', '{"question":"A short melody sounds finished when it ends on...","wrong_answer":"Any syllable","correct_answer":"d, the home note"}'::jsonb, 'The child has not felt d as home.', 'Offer "Any syllable" next to the right answer and ask the question again in a new context.', 'Sing d r m r then stop on r and then on d: which sounds finished?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.MELODY.SIGNS.M_CA4_ML_SIGN_DOWN', 'CREA.G4.CREATI.MELODY.SIGNS', 'Holds the hand lower for a higher sound.', '{"question":"The pitch goes higher from d to m. What does the hand do?","wrong_answer":"Moves lower","correct_answer":"Moves higher"}'::jsonb, 'The child links high with a heavy hand.', 'Offer "Moves lower" next to the right answer and ask the question again in a new context.', 'Sing d r m and raise your hand for each step.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.MELODY.SIGNS.M_CA4_ML_SIGN_MIX', 'CREA.G4.CREATI.MELODY.SIGNS', 'Mixes up which hand sign belongs to which syllable.', '{"question":"Which sign is a closed fist held low?","wrong_answer":"m","correct_answer":"d"}'::jsonb, 'The child has not matched sign and syllable.', 'Offer "m" next to the right answer and ask the question again in a new context.', 'Show each sign three times saying the syllable.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.MELODY.SIGNS.M_CA4_ML_M_FIST', 'CREA.G4.CREATI.MELODY.SIGNS', 'Says m is shown with a fist.', '{"question":"How is m shown?","wrong_answer":"With a closed fist","correct_answer":"With a flat hand, palm down"}'::jsonb, 'The child mixes up the signs of d and m.', 'Offer "With a closed fist" next to the right answer and ask the question again in a new context.', 'Show a fist for d and a flat hand for m, saying the sounds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.MELODY.MELQUAL.M_CA4_ML_ONE_SYLLABLE', 'CREA.G4.CREATI.MELODY.MELQUAL', 'Thinks a good melody uses one syllable only.', '{"question":"Which melody has variation?","wrong_answer":"m m m m","correct_answer":"d r m r"}'::jsonb, 'The child thinks repeating one sound is simple and good.', 'Offer "m m m m" next to the right answer and ask the question again in a new context.', 'Sing both and ask which is more interesting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.MELODY.MELQUAL.M_CA4_ML_END_NOT_D', 'CREA.G4.CREATI.MELODY.MELQUAL', 'Thinks a good melody ends on m.', '{"question":"A good short melody ends on...","wrong_answer":"m","correct_answer":"d"}'::jsonb, 'The child thinks the highest note is the best ending.', 'Offer "m" next to the right answer and ask the question again in a new context.', 'Sing the melody ending on m and on d and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.MELODY.MELQUAL.M_CA4_ML_STEP_JUMPS', 'CREA.G4.CREATI.MELODY.MELQUAL', 'Thinks stepwise motion means big jumps.', '{"question":"What does stepwise motion mean?","wrong_answer":"Jumping over syllables","correct_answer":"Moving to the next syllable"}'::jsonb, 'The child links step with a big stride.', 'Offer "Jumping over syllables" next to the right answer and ask the question again in a new context.', 'Walk stairs one by one and sing d r m.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.MELODY.CLAY.M_CA4_ML_CLAY_DRY', 'CREA.G4.CREATI.MELODY.CLAY', 'Thinks the clay should be dried hard before it is shaped.', '{"question":"What state should the clay be in for modelling?","wrong_answer":"Dry and hard","correct_answer":"Soft and damp"}'::jsonb, 'The child thinks hard means strong.', 'Offer "Dry and hard" next to the right answer and ask the question again in a new context.', 'Try to bend a dry clay lump and a damp one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.MELODY.CLAY.M_CA4_ML_CLAY_COIL', 'CREA.G4.CREATI.MELODY.CLAY', 'Says a coil is a flat sheet of clay.', '{"question":"What is a coil?","wrong_answer":"A flat sheet","correct_answer":"A rolled snake of clay"}'::jsonb, 'The child mixes up slab and coil.', 'Offer "A flat sheet" next to the right answer and ask the question again in a new context.', 'Roll one and flatten the other.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.MELODY.CLAY.M_CA4_ML_CLAY_STONES', 'CREA.G4.CREATI.MELODY.CLAY', 'Thinks stones can stay in the clay.', '{"question":"What is done to clay before modelling?","wrong_answer":"Nothing, use it as it is","correct_answer":"Stones are removed and it is kneaded"}'::jsonb, 'The child uses clay straight from the ground.', 'Offer "Nothing, use it as it is" next to the right answer and ask the question again in a new context.', 'Squeeze clay with a small stone in it and see it crack.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.MELODY.CLAY.M_CA4_ML_CLAY_GLUE', 'CREA.G4.CREATI.MELODY.CLAY', 'Says coils are stuck to the slab with glue.', '{"question":"What joins the coil letters to the slab?","wrong_answer":"Strong glue","correct_answer":"A little water on the clay"}'::jsonb, 'The child thinks clay needs glue.', 'Offer "Strong glue" next to the right answer and ask the question again in a new context.', 'Join two pieces with a little water and press.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.MELODY.SIGNS.M_CA4_ML_SIGN_HEIGHT', 'CREA.G4.CREATI.MELODY.SIGNS', 'Shows every hand sign at the same height, so the hands do not show pitch rising.', '{"question":"Where should the hand be for m compared with d?","wrong_answer":"at the same height","correct_answer":"higher than for d"}'::jsonb, 'The child learns the hand shapes but not that their height shows pitch.', 'Offer "at the same height" next to the right answer and ask the question again in a new context.', 'Sing d r m and raise the hand a little for each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.CREATI.MELODY.MELQUAL.M_CA4_ML_ALL_LEAPS', 'CREA.G4.CREATI.MELODY.MELQUAL', 'Thinks a good melody jumps about a lot to be exciting.', '{"question":"Which is easier to sing: d r m r d, or d m d m d m?","wrong_answer":"d m d m d m","correct_answer":"d r m r d"}'::jsonb, 'The child links excitement with big jumps.', 'Offer "d m d m d m" next to the right answer and ask the question again in a new context.', 'Sing both; ask which feels smooth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.ATHLETICS.STARTS.M_CA4_AT_COMMANDS_ORDER', 'CREA.G4.PERFOR.ATHLETICS.STARTS', 'Puts the start commands in the wrong order.', '{"question":"What is the first command at the start?","wrong_answer":"Go","correct_answer":"On your marks"}'::jsonb, 'The child remembers only the loud last word.', 'Offer "Go" next to the right answer and ask the question again in a new context.', 'Practise the three commands in a line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.ATHLETICS.STARTS.M_CA4_AT_SET_HIPS', 'CREA.G4.PERFOR.ATHLETICS.STARTS', 'Says the hips go down at the command Set.', '{"question":"What happens to the hips at Set?","wrong_answer":"They go down","correct_answer":"They are raised"}'::jsonb, 'The child tries to stay low and steady.', 'Offer "They go down" next to the right answer and ask the question again in a new context.', 'Show the position at Set and ask where the weight is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.ATHLETICS.STARTS.M_CA4_AT_ELONG_CLOSE', 'CREA.G4.PERFOR.ATHLETICS.STARTS', 'Says the feet are closest in the elongated start.', '{"question":"In which start are the feet furthest apart?","wrong_answer":"The medium start","correct_answer":"The elongated start"}'::jsonb, 'The child reads elongated as short.', 'Offer "The medium start" next to the right answer and ask the question again in a new context.', 'Mark the foot places in the sand for each start.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.ATHLETICS.STARTS.M_CA4_AT_LOOK_BACK', 'CREA.G4.PERFOR.ATHLETICS.STARTS', 'Says the runner looks at the other runners or behind at the start.', '{"question":"Where do the eyes look at the start?","wrong_answer":"At the other runners","correct_answer":"Down and ahead at the track"}'::jsonb, 'The child worries about others.', 'Offer "At the other runners" next to the right answer and ask the question again in a new context.', 'Say: you race your own lane.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.ATHLETICS.SPRINT.M_CA4_AT_ARMS_ACROSS', 'CREA.G4.PERFOR.ATHLETICS.SPRINT', 'Says the arms swing across the body.', '{"question":"How do the arms swing in sprinting?","wrong_answer":"Across the body","correct_answer":"Forward and back, bent"}'::jsonb, 'The child copies relaxed running.', 'Offer "Across the body" next to the right answer and ask the question again in a new context.', 'Run slowly with arms across and with arms forward and back.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.ATHLETICS.SPRINT.M_CA4_AT_HEELS', 'CREA.G4.PERFOR.ATHLETICS.SPRINT', 'Says a sprinter runs on the heels.', '{"question":"Which part of the foot does a sprinter use?","wrong_answer":"The heels","correct_answer":"The balls of the feet"}'::jsonb, 'The child copies walking.', 'Offer "The heels" next to the right answer and ask the question again in a new context.', 'Run on the heels for a few steps and feel the slowing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.ATHLETICS.SPRINT.M_CA4_AT_STOP_LINE', 'CREA.G4.PERFOR.ATHLETICS.SPRINT', 'Says a sprinter stops at the finish line.', '{"question":"What does a sprinter do at the finish line?","wrong_answer":"Slows down and stops before it","correct_answer":"Runs through the line"}'::jsonb, 'The child thinks the race ends before the line.', 'Offer "Slows down and stops before it" next to the right answer and ask the question again in a new context.', 'Run to a line and run through it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.ATHLETICS.SPRINT.M_CA4_AT_LOOK_DOWN', 'CREA.G4.PERFOR.ATHLETICS.SPRINT', 'Says a sprinter looks at the feet.', '{"question":"Where does a sprinter look when running?","wrong_answer":"At the feet","correct_answer":"Ahead"}'::jsonb, 'The child checks the feet for safety.', 'Offer "At the feet" next to the right answer and ask the question again in a new context.', 'Run looking ahead and notice the body stay straight.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.ATHLETICS.FLAG.M_CA4_AT_FLAG_ORDER', 'CREA.G4.PERFOR.ATHLETICS.FLAG', 'Gets the order of the flag colours wrong.', '{"question":"Which colour is at the top of the Kenyan flag?","wrong_answer":"Green","correct_answer":"Black"}'::jsonb, 'The child has not looked at the flag stripe by stripe.', 'Offer "Green" next to the right answer and ask the question again in a new context.', 'Colour the stripes in order and check with a real flag.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.ATHLETICS.FLAG.M_CA4_AT_FLAG_MEANING', 'CREA.G4.PERFOR.ATHLETICS.FLAG', 'Swaps the meanings of the flag colours, giving red the meaning of green (the land).', '{"question":"What does the red in the Kenyan flag stand for?","wrong_answer":"The land","correct_answer":"The blood shed for freedom"}'::jsonb, 'The child learns the colours and the meanings as two lists and pairs them by guessing.', 'Offer "The land" next to the right answer and ask the question again in a new context.', 'Match each colour to its meaning on a card.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.ATHLETICS.FLAG.M_CA4_AT_FLAG_WHY', 'CREA.G4.PERFOR.ATHLETICS.FLAG', 'Thinks the flag is flown only to decorate.', '{"question":"Why is the Kenyan flag flown at an event?","wrong_answer":"Only to decorate","correct_answer":"To show love of country and unity"}'::jsonb, 'The child sees only the colours.', 'Offer "Only to decorate" next to the right answer and ask the question again in a new context.', 'Ask where the flag flies and what it stands for.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.ATHLETICS.FLAG.M_CA4_AT_FLAG_SHIELD', 'CREA.G4.PERFOR.ATHLETICS.FLAG', 'Thinks the shield and spears stand for war.', '{"question":"What does the shield and spears on the Kenyan flag stand for?","wrong_answer":"war","correct_answer":"defence of freedom"}'::jsonb, 'Spears are weapons, so the child links them with fighting.', 'Offer "war" next to the right answer and ask the question again in a new context.', 'Read the meaning together: they defend freedom.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.GYMNASTICS.BALANCES.M_CA4_GY_CRAB_DOWN', 'CREA.G4.PERFOR.GYMNASTICS.BALANCES', 'Says the crab balance is done with the tummy facing the floor.', '{"question":"In a crab balance, which way does the tummy face?","wrong_answer":"Down","correct_answer":"Up"}'::jsonb, 'The child mixes it with a push-up.', 'Offer "Down" next to the right answer and ask the question again in a new context.', 'Sit down, put hands behind and lift the hips: the tummy faces up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.GYMNASTICS.BALANCES.M_CA4_GY_ROLL_HEAD', 'CREA.G4.PERFOR.GYMNASTICS.BALANCES', 'Says the side roll goes over the head.', '{"question":"In which direction does a side roll go?","wrong_answer":"Over the head, forwards","correct_answer":"Sideways along the mat"}'::jsonb, 'The child mixes it with a forward roll.', 'Offer "Over the head, forwards" next to the right answer and ask the question again in a new context.', 'Lie down and roll to the side with the body straight.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.GYMNASTICS.BALANCES.M_CA4_GY_ROLL_BENT', 'CREA.G4.PERFOR.GYMNASTICS.BALANCES', 'Says to bend the knees and curl up in the side roll.', '{"question":"What is the body like in a side roll?","wrong_answer":"Curled up in a ball","correct_answer":"Straight, arms above the head and legs together"}'::jsonb, 'The child mixes it with another roll.', 'Offer "Curled up in a ball" next to the right answer and ask the question again in a new context.', 'Roll once straight and once curled and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.GYMNASTICS.BALANCES.M_CA4_GY_CRAB_RUSH', 'CREA.G4.PERFOR.GYMNASTICS.BALANCES', 'Thinks the crab balance is done quickly and not held.', '{"question":"How long is a crab balance held?","wrong_answer":"No time, move at once","correct_answer":"Still, for a count of three"}'::jsonb, 'The child thinks speed is the skill.', 'Offer "No time, move at once" next to the right answer and ask the question again in a new context.', 'Hold and count three together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.GYMNASTICS.GYMSAFE.M_CA4_GY_NO_WARMUP', 'CREA.G4.PERFOR.GYMNASTICS.GYMSAFE', 'Thinks warming up wastes time.', '{"question":"What should you do before gymnastics?","wrong_answer":"Start straight away","correct_answer":"Warm up first"}'::jsonb, 'The child wants to start the fun part.', 'Offer "Start straight away" next to the right answer and ask the question again in a new context.', 'Say: a cold muscle can be hurt easily.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.GYMNASTICS.GYMSAFE.M_CA4_GY_HARD_GROUND', 'CREA.G4.PERFOR.GYMNASTICS.GYMSAFE', 'Thinks any floor is fine for gymnastics.', '{"question":"Where is gymnastics done?","wrong_answer":"On a hard stony floor","correct_answer":"On a mat or soft cleared ground"}'::jsonb, 'The child does not think of falling.', 'Offer "On a hard stony floor" next to the right answer and ask the question again in a new context.', 'Say: a fall on stones hurts, on a mat it does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.GYMNASTICS.GYMSAFE.M_CA4_GY_PAIN_GO_ON', 'CREA.G4.PERFOR.GYMNASTICS.GYMSAFE', 'Thinks you should keep going if a part hurts.', '{"question":"Your wrist hurts in a crab balance. What do you do?","wrong_answer":"Keep going","correct_answer":"Stop and tell the teacher"}'::jsonb, 'The child is afraid to look weak.', 'Offer "Keep going" next to the right answer and ask the question again in a new context.', 'Say: telling is brave and keeps you from a worse injury.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.GYMNASTICS.GYMSAFE.M_CA4_GY_SHOES', 'CREA.G4.PERFOR.GYMNASTICS.GYMSAFE', 'Thinks gymnastics is safer in hard school shoes.', '{"question":"Should you do a side roll in school shoes?","wrong_answer":"yes, shoes protect the feet","correct_answer":"no; bare feet or soft shoes on a mat"}'::jsonb, 'Shoes protect feet outside, so the child expects the same on a mat.', 'Offer "yes, shoes protect the feet" next to the right answer and ask the question again in a new context.', 'Show how a hard shoe can hit a partner or slip on a mat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SONGS.TYPES.M_CA4_SG_SACRED_PATRIOTIC', 'CREA.G4.PERFOR.SONGS.TYPES', 'Calls a song about God a patriotic song.', '{"question":"A song asks God to bless worshippers at church. What type is it?","wrong_answer":"Patriotic","correct_answer":"Sacred"}'::jsonb, 'The child mixes up praising God with praising the country.', 'Offer "Patriotic" next to the right answer and ask the question again in a new context.', 'Ask: who is the song about, God or the country?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SONGS.TYPES.M_CA4_SG_TOPICAL_ANY', 'CREA.G4.PERFOR.SONGS.TYPES', 'Thinks a topical song is any song sung at school.', '{"question":"Which is a topical song?","wrong_answer":"A hymn at church","correct_answer":"A song about washing hands to stop germs"}'::jsonb, 'The child does not know topical means about the topic of the day.', 'Offer "A hymn at church" next to the right answer and ask the question again in a new context.', 'List issues people talk about now, and match a song to one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SONGS.TYPES.M_CA4_SG_PATRIOTIC_LOVE', 'CREA.G4.PERFOR.SONGS.TYPES', 'Thinks a patriotic song is about love for a friend.', '{"question":"What is a patriotic song about?","wrong_answer":"Love for a friend","correct_answer":"Love for the country"}'::jsonb, 'The child knows the word love and not patriot.', 'Offer "Love for a friend" next to the right answer and ask the question again in a new context.', 'Link patriot to the word country (patria).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SONGS.PERFTERMS.M_CA4_SG_TEMPO_LOUD', 'CREA.G4.PERFOR.SONGS.PERFTERMS', 'Says tempo means how loud the song is.', '{"question":"What does tempo mean?","wrong_answer":"How loud it is","correct_answer":"How fast it is"}'::jsonb, 'The child mixes tempo with dynamics.', 'Offer "How loud it is" next to the right answer and ask the question again in a new context.', 'Sing a song fast and slow, then loud and soft.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SONGS.PERFTERMS.M_CA4_SG_DYNAMICS_FAST', 'CREA.G4.PERFOR.SONGS.PERFTERMS', 'Says dynamics mean how fast the song is.', '{"question":"What do dynamics mean?","wrong_answer":"The speed","correct_answer":"How loud or soft"}'::jsonb, 'The child mixes dynamics with tempo.', 'Offer "The speed" next to the right answer and ask the question again in a new context.', 'Sing the same line loud then soft.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SONGS.PERFTERMS.M_CA4_SG_UNISON_PARTS', 'CREA.G4.PERFOR.SONGS.PERFTERMS', 'Thinks unison means everyone sings a different part.', '{"question":"What does singing in unison mean?","wrong_answer":"Each group sings a different part","correct_answer":"Everyone sings the same notes together"}'::jsonb, 'The child mixes unison with parts or a round.', 'Offer "Each group sings a different part" next to the right answer and ask the question again in a new context.', 'Sing a line all together, then in two groups, and name each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SONGS.PERFTERMS.M_CA4_SG_PITCH_SPEED', 'CREA.G4.PERFOR.SONGS.PERFTERMS', 'Says pitch is how fast a song is.', '{"question":"What is pitch?","wrong_answer":"How fast the song goes","correct_answer":"How high or low a sound is"}'::jsonb, 'The child mixes pitch with tempo.', 'Offer "How fast the song goes" next to the right answer and ask the question again in a new context.', 'Sing a high and a low note.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SONGS.EAC.M_CA4_SG_EAC_SIT', 'CREA.G4.PERFOR.SONGS.EAC', 'Thinks the anthem can be sung sitting or moving about.', '{"question":"How do you behave when the anthem is sung?","wrong_answer":"Sit and talk","correct_answer":"Stand straight and still"}'::jsonb, 'The child thinks it is just a song.', 'Offer "Sit and talk" next to the right answer and ask the question again in a new context.', 'Say: an anthem is a song of respect.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SONGS.EAC.M_CA4_SG_EAC_PARTS', 'CREA.G4.PERFOR.SONGS.EAC', 'Thinks the anthem is sung in different parts or a round.', '{"question":"The anthem is sung...","wrong_answer":"In a round","correct_answer":"In unison"}'::jsonb, 'The child mixes it up with rounds.', 'Offer "In a round" next to the right answer and ask the question again in a new context.', 'Sing it together and sing a round to compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SONGS.EAC.M_CA4_SG_EAC_MESSAGE', 'CREA.G4.PERFOR.SONGS.EAC', 'Says the anthem is about only one country.', '{"question":"What is the anthem about?","wrong_answer":"Only Kenya","correct_answer":"East Africa: God blessing us with peace and unity"}'::jsonb, 'The child mixes it up with the Kenya National Anthem.', 'Offer "Only Kenya" next to the right answer and ask the question again in a new context.', 'Name the countries of East Africa on a map and say they sing it together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SONGS.FOLKTYPES.M_CA4_SG_FOLK_FUNERAL_WORK', 'CREA.G4.PERFOR.SONGS.FOLKTYPES', 'Mixes up work and funeral songs.', '{"question":"Women sing while grinding millet. What type of folk song is it?","wrong_answer":"A funeral song","correct_answer":"A work song"}'::jsonb, 'The child links the sad voice with funeral.', 'Offer "A funeral song" next to the right answer and ask the question again in a new context.', 'Ask: when is it sung, and what is happening?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SONGS.FOLKTYPES.M_CA4_SG_FOLK_NAMING', 'CREA.G4.PERFOR.SONGS.FOLKTYPES', 'Says a naming song is sung at a wedding.', '{"question":"A song welcomes a new baby. What type is it?","wrong_answer":"A marriage song","correct_answer":"A naming song"}'::jsonb, 'The child mixes celebration songs.', 'Offer "A marriage song" next to the right answer and ask the question again in a new context.', 'Ask: who is being celebrated?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SONGS.FOLKTYPES.M_CA4_SG_FOLK_ALL_SAME', 'CREA.G4.PERFOR.SONGS.FOLKTYPES', 'Thinks all communities sing the same songs.', '{"question":"Do all Kenyan communities sing the same folk songs?","wrong_answer":"Yes, they are all the same","correct_answer":"No, each community has its own songs"}'::jsonb, 'The child has heard few songs.', 'Offer "Yes, they are all the same" next to the right answer and ask the question again in a new context.', 'Listen to songs from two communities.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SONGS.TYPES.M_CA4_SG_SACRED_ANY_CHURCH', 'CREA.G4.PERFOR.SONGS.TYPES', 'Thinks any song sung in church is sacred, whatever its words.', '{"question":"A song about road safety is sung at a church event. Is it sacred?","wrong_answer":"yes","correct_answer":"no; it is topical"}'::jsonb, 'The child sorts by place, not by message.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Read the words: what are they about?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SONGS.EAC.M_CA4_SG_EAC_KENYA_ONLY', 'CREA.G4.PERFOR.SONGS.EAC', 'Thinks the EAC anthem is only for Kenya.', '{"question":"Which countries sing the East African Community anthem?","wrong_answer":"only Kenya","correct_answer":"all the partner states of the East African Community"}'::jsonb, 'The child knows only one anthem belongs to a country.', 'Offer "only Kenya" next to the right answer and ask the question again in a new context.', 'Name some partner states on a map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SONGS.FOLKTYPES.M_CA4_SG_FOLK_RADIO', 'CREA.G4.PERFOR.SONGS.FOLKTYPES', 'Thinks a pop song heard on the radio is a folk song.', '{"question":"Is a new pop song on the radio a folk song?","wrong_answer":"yes","correct_answer":"no; a folk song comes from a community and is passed down"}'::jsonb, 'Both are songs people know, so the child mixes them.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Ask who made it and how old it is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.PHOTOGRAPHY.DEVICES.M_CA4_PH_TV_CAMERA', 'CREA.G4.PERFOR.PHOTOGRAPHY.DEVICES', 'Thinks a television or a radio takes photographs.', '{"question":"Which of these takes photographs?","wrong_answer":"A television","correct_answer":"A phone camera"}'::jsonb, 'The child sees screens and thinks any screen takes pictures.', 'Offer "A television" next to the right answer and ask the question again in a new context.', 'Sort devices by whether they have a lens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.PHOTOGRAPHY.DEVICES.M_CA4_PH_NO_ASK', 'CREA.G4.PERFOR.PHOTOGRAPHY.DEVICES', 'Thinks you may photograph anyone without asking.', '{"question":"Before taking a photograph of a person, what should you do?","wrong_answer":"Take it quickly","correct_answer":"Ask permission"}'::jsonb, 'The child thinks a photograph does no harm.', 'Offer "Take it quickly" next to the right answer and ask the question again in a new context.', 'Ask: how would you feel if someone photographed you without asking?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.PHOTOGRAPHY.DEVICES.M_CA4_PH_CARELESS', 'CREA.G4.PERFOR.PHOTOGRAPHY.DEVICES', 'Thinks a device may be dropped, wet or touched on the lens.', '{"question":"How should you handle a camera?","wrong_answer":"With wet hands, by one finger","correct_answer":"With both hands and a clean, dry lens"}'::jsonb, 'The child does not think of cost.', 'Offer "With wet hands, by one finger" next to the right answer and ask the question again in a new context.', 'Show a smudged lens photo and a clean one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.PHOTOGRAPHY.ELEMENTS.M_CA4_PH_SUN_BEHIND_SUBJECT', 'CREA.G4.PERFOR.PHOTOGRAPHY.ELEMENTS', 'Thinks the best photo is with the sun behind the person.', '{"question":"Where should the sun be for a good photograph?","wrong_answer":"Behind the person being photographed","correct_answer":"Behind the photographer"}'::jsonb, 'The child thinks bright light is always good.', 'Offer "Behind the person being photographed" next to the right answer and ask the question again in a new context.', 'Take two photos, one each way, and compare the faces.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.PHOTOGRAPHY.ELEMENTS.M_CA4_PH_CENTRE_SMALL', 'CREA.G4.PERFOR.PHOTOGRAPHY.ELEMENTS', 'Thinks the main subject can be a tiny dot in a big picture.', '{"question":"The centre of interest in a photograph should be...","wrong_answer":"Very small at the edge","correct_answer":"Clear and easy to see"}'::jsonb, 'The child wants to fit everything in.', 'Offer "Very small at the edge" next to the right answer and ask the question again in a new context.', 'Take a photo close up and from far and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.PHOTOGRAPHY.ELEMENTS.M_CA4_PH_CENTRE_MEANING', 'CREA.G4.PERFOR.PHOTOGRAPHY.ELEMENTS', 'Thinks centre of interest means the middle of the room.', '{"question":"What is the centre of interest?","wrong_answer":"The middle of the room","correct_answer":"The main thing the photograph is about"}'::jsonb, 'The child takes the word centre literally.', 'Offer "The middle of the room" next to the right answer and ask the question again in a new context.', 'Ask: what do you want people to look at?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.PHOTOGRAPHY.DEVICES.M_CA4_PH_RADIO_CAMERA', 'CREA.G4.PERFOR.PHOTOGRAPHY.DEVICES', 'Thinks a radio can take photographs because it is an electronic device.', '{"question":"Can a radio take a photograph?","wrong_answer":"yes","correct_answer":"no; it has no camera"}'::jsonb, 'Electronic devices look alike to the child.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Look for the lens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.PHOTOGRAPHY.ELEMENTS.M_CA4_PH_TILT', 'CREA.G4.PERFOR.PHOTOGRAPHY.ELEMENTS', 'Thinks tilting the device does not change the photo.', '{"question":"Your phone is tilted. What happens to the photo?","wrong_answer":"nothing","correct_answer":"the picture comes out slanted"}'::jsonb, 'The child does not link the device angle to the picture.', 'Offer "nothing" next to the right answer and ask the question again in a new context.', 'Take two photos, straight and tilted, and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.DESCANT_RECORDER.RECPARTS.M_CA4_DR_PARTS_BLOW', 'CREA.G4.PERFOR.DESCANT_RECORDER.RECPARTS', 'Says the player blows into the foot joint.', '{"question":"Where does the player blow?","wrong_answer":"The foot joint","correct_answer":"The mouthpiece on the head joint"}'::jsonb, 'The child mixes up the ends.', 'Offer "The foot joint" next to the right answer and ask the question again in a new context.', 'Hold a recorder and point to the mouthpiece.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.DESCANT_RECORDER.RECPARTS.M_CA4_DR_PARTS_HOLES', 'CREA.G4.PERFOR.DESCANT_RECORDER.RECPARTS', 'Says the finger holes are on the head joint.', '{"question":"Where are most of the finger holes?","wrong_answer":"The head joint","correct_answer":"The middle joint"}'::jsonb, 'The child does not look at where the fingers go.', 'Offer "The head joint" next to the right answer and ask the question again in a new context.', 'Name the joints while placing fingers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.DESCANT_RECORDER.RECPARTS.M_CA4_DR_PARTS_NAMES', 'CREA.G4.PERFOR.DESCANT_RECORDER.RECPARTS', 'Mixes up the names of the three joints.', '{"question":"Which is the lowest part?","wrong_answer":"The head joint","correct_answer":"The foot joint"}'::jsonb, 'The child has not named the joints in order.', 'Offer "The head joint" next to the right answer and ask the question again in a new context.', 'Name them from top to bottom: head, middle, foot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.DESCANT_RECORDER.CARE.M_CA4_DR_HOT_WATER', 'CREA.G4.PERFOR.DESCANT_RECORDER.CARE', 'Thinks a recorder is cleaned with boiling water.', '{"question":"How is a recorder cleaned?","wrong_answer":"In boiling water","correct_answer":"In clean warm water, then dried"}'::jsonb, 'The child thinks hotter cleans better.', 'Offer "In boiling water" next to the right answer and ask the question again in a new context.', 'Say: hot water can bend the plastic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.DESCANT_RECORDER.CARE.M_CA4_DR_SHARE', 'CREA.G4.PERFOR.DESCANT_RECORDER.CARE', 'Thinks sharing a recorder without cleaning is fine.', '{"question":"Wanjiku wants to use Otieno''s recorder. What first?","wrong_answer":"Use it at once","correct_answer":"Clean the mouthpiece"}'::jsonb, 'The child sees it as sharing.', 'Offer "Use it at once" next to the right answer and ask the question again in a new context.', 'Link to sharing a cup.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.DESCANT_RECORDER.CARE.M_CA4_DR_STORE', 'CREA.G4.PERFOR.DESCANT_RECORDER.CARE', 'Thinks a recorder may be left in the sun or in a damp place.', '{"question":"Where should a recorder be kept?","wrong_answer":"In the sun on the desk","correct_answer":"Dry, in a bag or case, away from heat"}'::jsonb, 'The child is not thinking about heat.', 'Offer "In the sun on the desk" next to the right answer and ask the question again in a new context.', 'Show a bent recorder from heat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.DESCANT_RECORDER.NOTES.M_CA4_DR_MORE_HIGHER', 'CREA.G4.PERFOR.DESCANT_RECORDER.NOTES', 'Thinks covering more holes gives a higher note.', '{"question":"Which note covers the most holes?","wrong_answer":"B","correct_answer":"G"}'::jsonb, 'The child thinks more means higher.', 'Offer "B" next to the right answer and ask the question again in a new context.', 'Play B A G and watch the fingers go down.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.DESCANT_RECORDER.NOTES.M_CA4_DR_FINGERS_MIX', 'CREA.G4.PERFOR.DESCANT_RECORDER.NOTES', 'Mixes up how many fingers each note needs.', '{"question":"How many fingers (with the thumb) does A need?","wrong_answer":"One finger","correct_answer":"Two fingers"}'::jsonb, 'The child has not matched note and fingering.', 'Offer "One finger" next to the right answer and ask the question again in a new context.', 'Make a chart: B one, A two, G three.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.DESCANT_RECORDER.NOTES.M_CA4_DR_ORDER', 'CREA.G4.PERFOR.DESCANT_RECORDER.NOTES', 'Puts the notes B A G in order from low to high as B, A, G.', '{"question":"Which is the right order from low to high?","wrong_answer":"B, A, G","correct_answer":"G, A, B"}'::jsonb, 'The child reads the order as it is written.', 'Offer "B, A, G" next to the right answer and ask the question again in a new context.', 'Play them and listen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.DESCANT_RECORDER.TECHNIQUE.M_CA4_DR_BLOW_HARD', 'CREA.G4.PERFOR.DESCANT_RECORDER.TECHNIQUE', 'Thinks you should blow hard to get a good sound.', '{"question":"How hard should you blow?","wrong_answer":"As hard as you can","correct_answer":"Gently and steadily"}'::jsonb, 'The child thinks louder is better.', 'Offer "As hard as you can" next to the right answer and ask the question again in a new context.', 'Blow gently and hard and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.DESCANT_RECORDER.TECHNIQUE.M_CA4_DR_TIP_FINGERS', 'CREA.G4.PERFOR.DESCANT_RECORDER.TECHNIQUE', 'Thinks you cover holes with the tip of the finger.', '{"question":"How do you cover a hole?","wrong_answer":"With the tip of the finger","correct_answer":"With the soft pad of the finger"}'::jsonb, 'The child holds the recorder loosely.', 'Offer "With the tip of the finger" next to the right answer and ask the question again in a new context.', 'Press a pad and a tip on a hole and see the leak.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.DESCANT_RECORDER.TECHNIQUE.M_CA4_DR_SLOUCH', 'CREA.G4.PERFOR.DESCANT_RECORDER.TECHNIQUE', 'Thinks posture does not matter.', '{"question":"How should you sit to play?","wrong_answer":"Slouched, to relax","correct_answer":"Sitting tall, recorder in front"}'::jsonb, 'The child is comfortable slouched.', 'Offer "Slouched, to relax" next to the right answer and ask the question again in a new context.', 'Try breathing slouched and tall.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.DESCANT_RECORDER.RECPARTS.M_CA4_DR_PARTS_THUMB', 'CREA.G4.PERFOR.DESCANT_RECORDER.RECPARTS', 'Thinks the hole at the back is for blowing.', '{"question":"What is the hole at the back of the recorder for?","wrong_answer":"for blowing","correct_answer":"the left thumb covers it"}'::jsonb, 'The child sees a hole and thinks of air going in.', 'Offer "for blowing" next to the right answer and ask the question again in a new context.', 'Hold the recorder; find which finger covers the back hole.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.DESCANT_RECORDER.CARE.M_CA4_DR_SUN', 'CREA.G4.PERFOR.DESCANT_RECORDER.CARE', 'Leaves the recorder in hot sun to dry it.', '{"question":"Where should a wet recorder dry?","wrong_answer":"in hot sun","correct_answer":"in the shade, after shaking out water"}'::jsonb, 'Sun dries clothes, so the child expects the same.', 'Offer "in hot sun" next to the right answer and ask the question again in a new context.', 'Explain that heat can bend plastic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.DESCANT_RECORDER.NOTES.M_CA4_DR_RIGHT_HAND', 'CREA.G4.PERFOR.DESCANT_RECORDER.NOTES', 'Plays B, A, G with the right hand.', '{"question":"Which hand plays B, A and G?","wrong_answer":"the right hand","correct_answer":"the left hand, on top"}'::jsonb, 'The child uses the hand they write with.', 'Offer "the right hand" next to the right answer and ask the question again in a new context.', 'Put the left hand on top, near the mouthpiece.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.DESCANT_RECORDER.TECHNIQUE.M_CA4_DR_NO_TONGUE', 'CREA.G4.PERFOR.DESCANT_RECORDER.TECHNIQUE', 'Starts every note with a push of breath and no tongue.', '{"question":"How do you start a note on the recorder?","wrong_answer":"push air hard","correct_answer":"say \"doo\" with the tongue"}'::jsonb, 'The child does not know the tongue starts notes.', 'Offer "push air hard" next to the right answer and ask the question again in a new context.', 'Whisper "doo" into the recorder.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SWIMMING.SAFETY.M_CA4_SW_DIVE_SHALLOW', 'CREA.G4.PERFOR.SWIMMING.SAFETY', 'Thinks diving into shallow water is fine.', '{"question":"How do you enter the water at the shallow end?","wrong_answer":"Dive in head first","correct_answer":"Feet first"}'::jsonb, 'The child sees divers on TV.', 'Offer "Dive in head first" next to the right answer and ask the question again in a new context.', 'Say: the bottom is close.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SWIMMING.SAFETY.M_CA4_SW_RUN_SIDE', 'CREA.G4.PERFOR.SWIMMING.SAFETY', 'Thinks running on the pool side is fine.', '{"question":"How do you move on the pool side?","wrong_answer":"Run","correct_answer":"Walk"}'::jsonb, 'The child is excited.', 'Offer "Run" next to the right answer and ask the question again in a new context.', 'Say: the floor is wet and slippery.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SWIMMING.SAFETY.M_CA4_SW_ALONE', 'CREA.G4.PERFOR.SWIMMING.SAFETY', 'Thinks it is fine to swim alone if you can swim.', '{"question":"May you swim alone?","wrong_answer":"Yes, if you can swim","correct_answer":"No, always with a teacher or lifeguard"}'::jsonb, 'The child trusts own ability.', 'Offer "Yes, if you can swim" next to the right answer and ask the question again in a new context.', 'Say: accidents are sudden.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SWIMMING.SAFETY.M_CA4_SW_PUSH', 'CREA.G4.PERFOR.SWIMMING.SAFETY', 'Thinks pushing a friend into the water is a fun game.', '{"question":"A friend stands at the edge. What do you do?","wrong_answer":"Push them in for fun","correct_answer":"Leave them alone and wait your turn"}'::jsonb, 'The child thinks it is a joke.', 'Offer "Push them in for fun" next to the right answer and ask the question again in a new context.', 'Say: they may hit the edge or not swim.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SWIMMING.FLOAT.M_CA4_SW_MUSHROOM_STRETCH', 'CREA.G4.PERFOR.SWIMMING.FLOAT', 'Says a mushroom float is stretched out.', '{"question":"In a mushroom float the body is...","wrong_answer":"Stretched out flat","correct_answer":"Curled up with knees hugged"}'::jsonb, 'The child mixes it with a star float.', 'Offer "Stretched out flat" next to the right answer and ask the question again in a new context.', 'Curl up like a mushroom.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SWIMMING.FLOAT.M_CA4_SW_SUPINE_FACE', 'CREA.G4.PERFOR.SWIMMING.FLOAT', 'Says a back float has the face in the water.', '{"question":"In a back (supine) float the face is...","wrong_answer":"In the water","correct_answer":"Up, with ears in the water"}'::jsonb, 'The child mixes up prone and supine.', 'Offer "In the water" next to the right answer and ask the question again in a new context.', 'Lie on the back and look up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SWIMMING.FLOAT.M_CA4_SW_GLIDE_ARMS', 'CREA.G4.PERFOR.SWIMMING.FLOAT', 'Says in a glide the arms stay by the sides.', '{"question":"In a glide the arms are...","wrong_answer":"By the sides","correct_answer":"Stretched ahead"}'::jsonb, 'The child does not know streamlining.', 'Offer "By the sides" next to the right answer and ask the question again in a new context.', 'Glide with arms ahead and by the sides.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SWIMMING.FLOAT.M_CA4_SW_TENSE', 'CREA.G4.PERFOR.SWIMMING.FLOAT', 'Thinks you must tense up to float.', '{"question":"To float, the body should be...","wrong_answer":"Tense and stiff","correct_answer":"Relaxed"}'::jsonb, 'The child fights the water.', 'Offer "Tense and stiff" next to the right answer and ask the question again in a new context.', 'Relax and float.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SWIMMING.ANIMAL.M_CA4_SW_FROG_CRAWL', 'CREA.G4.PERFOR.SWIMMING.ANIMAL', 'Mixes up frog jump and crab walk.', '{"question":"Which game is done with tummy up on hands and feet?","wrong_answer":"Frog jump","correct_answer":"Crab walk"}'::jsonb, 'The child mixes up the two games.', 'Offer "Frog jump" next to the right answer and ask the question again in a new context.', 'Do both and say the animal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SWIMMING.ANIMAL.M_CA4_SW_GAME_BUILDS', 'CREA.G4.PERFOR.SWIMMING.ANIMAL', 'Says the frog jump builds the arms, picking the body part that looks busy rather than the one that does the work.', '{"question":"The frog jump builds...","wrong_answer":"Arm strength only","correct_answer":"Leg strength"}'::jsonb, 'The arms swing in the jump, so the child thinks they are doing the work.', 'Offer "Arm strength only" next to the right answer and ask the question again in a new context.', 'Feel which muscles work.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SWIMMING.ANIMAL.M_CA4_SW_GAME_NEW', 'CREA.G4.PERFOR.SWIMMING.ANIMAL', 'Thinks animal games are new and were not played in the past.', '{"question":"Animal games are...","wrong_answer":"Only new games from television","correct_answer":"Indigenous games played long ago for fun and fitness"}'::jsonb, 'The child knows only modern games.', 'Offer "Only new games from television" next to the right answer and ask the question again in a new context.', 'Ask grandparents which games they played.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.PERFOR.SWIMMING.ANIMAL.M_CA4_SW_GAME_NO_RULES', 'CREA.G4.PERFOR.SWIMMING.ANIMAL', 'Thinks indigenous games have no rules because they are played for fun.', '{"question":"Do indigenous animal games have rules?","wrong_answer":"no","correct_answer":"yes; each game has rules everyone follows"}'::jsonb, 'Fun play feels free to the child.', 'Offer "no" next to the right answer and ask the question again in a new context.', 'Play one game and name its rules.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.CONCEPT.M_CA4_AP_COPY', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.CONCEPT', 'Thinks appreciation means copying a work.', '{"question":"What does appreciation mean?","wrong_answer":"Copying the work","correct_answer":"Looking carefully and thinking about what is good"}'::jsonb, 'The child links learning with copying.', 'Offer "Copying the work" next to the right answer and ask the question again in a new context.', 'Look at a picture and say two good things.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.CONCEPT.M_CA4_AP_ONLY_FAULT', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.CONCEPT', 'Thinks feedback means only saying what is wrong.', '{"question":"Which is kind and helpful feedback?","wrong_answer":"It is ugly and wrong","correct_answer":"I like your colours. Add more detail to the sky."}'::jsonb, 'The child thinks critique means fault finding.', 'Offer "It is ugly and wrong" next to the right answer and ask the question again in a new context.', 'Practise two good things and one idea.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.CONCEPT.M_CA4_AP_TOUCH', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.CONCEPT', 'Thinks you may touch displayed works.', '{"question":"At an exhibition you...","wrong_answer":"Touch the works to see them better","correct_answer":"Look but do not touch"}'::jsonb, 'The child wants to feel the work.', 'Offer "Touch the works to see them better" next to the right answer and ask the question again in a new context.', 'Ask: what if everyone touches?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.PORTFOLIO.M_CA4_AP_PORT_ANY', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.PORTFOLIO', 'Thinks a portfolio holds any papers.', '{"question":"A portfolio holds...","wrong_answer":"Any papers","correct_answer":"A learner''s best works"}'::jsonb, 'The child sees it as a folder for everything.', 'Offer "Any papers" next to the right answer and ask the question again in a new context.', 'Choose best works together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.PORTFOLIO.M_CA4_AP_PORT_BUY', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.PORTFOLIO', 'Thinks a portfolio must be bought.', '{"question":"A portfolio can be made from...","wrong_answer":"Only a bought leather case","correct_answer":"Local things such as cardboard or an old file"}'::jsonb, 'The child thinks only bought things are good.', 'Offer "Only a bought leather case" next to the right answer and ask the question again in a new context.', 'Make one from cardboard.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.PORTFOLIO.M_CA4_AP_PORT_LABEL', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.PORTFOLIO', 'Thinks works need no name or date.', '{"question":"What goes on each work?","wrong_answer":"Nothing","correct_answer":"Name and date"}'::jsonb, 'The child sees no use.', 'Offer "Nothing" next to the right answer and ask the question again in a new context.', 'Mix two works with no labels.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.ANTHEM.M_CA4_AP_KNA_VERSES', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.ANTHEM', 'Says the anthem has five verses, counting the lines or the times it is repeated, not the three stanzas.', '{"question":"How many verses does the Kenya National Anthem have?","wrong_answer":"Five","correct_answer":"Three"}'::jsonb, 'At assembly only one stanza is often sung, so the child guesses the count.', 'Offer "Five" next to the right answer and ask the question again in a new context.', 'Count the verses on a printed copy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.ANTHEM.M_CA4_AP_KNA_SING', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.ANTHEM', 'Thinks you may sit or talk while it is sung.', '{"question":"When the anthem is sung you...","wrong_answer":"Talk and move about","correct_answer":"Stand straight and still"}'::jsonb, 'The child thinks it is just a song.', 'Offer "Talk and move about" next to the right answer and ask the question again in a new context.', 'Say: respect for the country.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.ANTHEM.M_CA4_AP_KNA_WHAT', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.ANTHEM', 'Says the anthem is a song about a football match.', '{"question":"The Kenya National Anthem is a...","wrong_answer":"Song about sport","correct_answer":"Prayer asking God to bless Kenya, with peace and unity"}'::jsonb, 'The child knows it from sports events.', 'Offer "Song about sport" next to the right answer and ask the question again in a new context.', 'Read the words together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.FOLKPERF.M_CA4_AP_SOLOIST_ALL', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.FOLKPERF', 'Calls the whole group the soloist.', '{"question":"The soloist is...","wrong_answer":"The whole group","correct_answer":"The one singer who leads"}'::jsonb, 'The child hears the lead voice and the answer as one.', 'Offer "The whole group" next to the right answer and ask the question again in a new context.', 'Sing a call and response and name the roles.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.FOLKPERF.M_CA4_AP_SINGERS_PLAY', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.FOLKPERF', 'Says the singers play the instruments.', '{"question":"Who plays the instruments?","wrong_answer":"The singers who answer","correct_answer":"The instrumentalists"}'::jsonb, 'The child mixes the roles.', 'Offer "The singers who answer" next to the right answer and ask the question again in a new context.', 'Name the roles on a card.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.FOLKPERF.M_CA4_AP_MESSAGE', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.FOLKPERF', 'Thinks the message is the tune.', '{"question":"The message of a song is...","wrong_answer":"Its tune","correct_answer":"What its words say"}'::jsonb, 'The child mixes up tune and message.', 'Offer "Its tune" next to the right answer and ask the question again in a new context.', 'Ask: what are the words about?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.CONCEPT.M_CA4_AP_LIKE_ONLY', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.CONCEPT', 'Thinks appreciating art means only saying "I like it".', '{"question":"Your friend shows a drawing. Which is appreciation?","wrong_answer":"I like it","correct_answer":"I like how the dark shading makes the drum look round"}'::jsonb, 'The child has not learnt to say why.', 'Offer "I like it" next to the right answer and ask the question again in a new context.', 'Add "because" to every comment.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.PORTFOLIO.M_CA4_AP_PORT_BEST_ONLY', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.PORTFOLIO', 'Thinks a portfolio keeps only finished, best work.', '{"question":"Should your sketches go in your portfolio?","wrong_answer":"no, only the best work","correct_answer":"yes; it shows how your work grew"}'::jsonb, 'The child thinks a portfolio is a display.', 'Offer "no, only the best work" next to the right answer and ask the question again in a new context.', 'Show a sketch and the final piece side by side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.ANTHEM.M_CA4_AP_KNA_LANGUAGE', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.ANTHEM', 'Thinks the anthem is only sung in Kiswahili.', '{"question":"In which languages is the Kenya National Anthem sung?","wrong_answer":"only Kiswahili","correct_answer":"Kiswahili and English"}'::jsonb, 'The child has heard it in one language at assembly.', 'Offer "only Kiswahili" next to the right answer and ask the question again in a new context.', 'Sing one verse in each language.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.FOLKPERF.M_CA4_AP_COSTUME_ANY', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.FOLKPERF', 'Thinks any clothes count as a costume in a folk performance.', '{"question":"What is a costume in a folk song performance?","wrong_answer":"any clothes","correct_answer":"special dress of the community used for the performance"}'::jsonb, 'The child calls everyday clothes costume.', 'Offer "any clothes" next to the right answer and ask the question again in a new context.', 'Show a picture of a performance costume.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
