-- =====================================================================
-- HOREB: Grade 4 Creative Arts skills, prerequisites and misconceptions (owner, 18 Nov 2026)
-- =====================================================================
-- NOT RUN. Run in Supabase Dashboard -> SQL Editor, after 20261110_curriculum.sql (the five curriculum tables); prerequisites may name skills of the grade below, with no foreign key on them. Idempotent: safe to run twice.
-- WHY: Creative Arts Grade 4 skills and misconceptions were in the repository (curriculum/creative_arts/g4.json) but no HOREB migration loaded them; the depth pass of 18 Nov 2026 brought every skill to two or more prerequisites and four misconceptions, with a teaching pack. This loads 40 skills (proposed), 85 prerequisites (proposed) and 160 misconceptions (draft)
-- for 12 of 12 sub-strands, for the teacher reviewer. Outcomes are KICD's own words and are not changed.
-- GENERATED by scripts/build-maths-sql-grade.mjs creative_arts from curriculum/creative_arts/g4.json. Do not edit by hand.
-- The sub-strands and outcomes are inserted first (do nothing if present) so the foreign keys hold.
-- Sub-strands loaded: Percussion Musical Instruments (Drawing), Netball, Painting and Montage, Rhythm, Melody, Athletics, Gymnastics, Songs, Photography, Descant Recorder, Swimming, Analysis of Creative Arts works.
-- =====================================================================
BEGIN;
DELETE FROM public.curriculum_prerequisites WHERE skill_code LIKE 'CREA.G4.%' AND requires_kind = 'outcome' AND status = 'proposed' AND (skill_code || '|' || requires_code) <> ALL (ARRAY['CREA.G4.CREATI.PERCUSSION_MUSICAL_INSTR.ID|CREA.G3.PERFOR.STRING_MUSICAL_INSTRUMEN.d', 'CREA.G4.CREATI.RHYTHM.VALUES|MATH.G4.NUMBER.FRACTIONS.b', 'CREA.G4.CREATI.MELODY.MELQUAL|CREA.G3.CREATI.MELODY.d', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.CONCEPT|CREA.G3.CREATI.COLLAGE.d']::text[]);
COMMIT;
